            internal bool SetSimulationActive(bool active)
            {
                if (m_SimulationActive == active)
                    return false;

                m_Storage.simulationActive = active;
                m_SimulationActive = active;
                return true;
            }

            internal bool SetRendererActive(bool active)
            {
                bool lightsActive = active
                    && m_System != null
                    && m_System.lights.isActive
                    && m_System.lights.light != null
                    && m_System.lights.maxLights > 0;
                bool trailsActive = active
                    && m_System != null
                    && m_System.trails.isActive
                    && m_System.trails.mode == VividParticleTrailMode.PerParticle;
                if (m_RendererActive == active
                    && m_LightsActive == lightsActive
                    && m_TrailsActive == trailsActive)
                {
                    return false;
                }

                if (m_RendererActive != active)
                    m_Storage.rendererActive = active;
                if (m_LightsActive != lightsActive)
                    m_Storage.lightsActive = lightsActive;
                if (m_TrailsActive != trailsActive)
                    m_Storage.trailsActive = trailsActive;
                m_RendererActive = active;
                m_LightsActive = lightsActive;
                m_TrailsActive = trailsActive;
                return true;
            }

            internal bool hasPendingSimulation => m_HasPendingSimulation || m_HasPendingJob;

            internal bool hasPendingSimulationJob => m_HasPendingStandaloneJob;

            internal JobHandle pendingSimulationJob => m_PendingJob;

            internal bool requiresCurrentFrameSimulationCompletion
            {
                get
                {
                    if (LastCompletedFrame < 0 || m_System == null)
                        return true;

                    VividParticleSubEmittersModule subEmitters = m_System.subEmitters;
                    if (subEmitters.enabled)
                    {
                        for (int index = 0; index < subEmitters.subEmittersCount; index++)
                        {
                            if (subEmitters.GetSubEmitterSystem(index) != null)
                                return true;
                        }
                    }

                    if (m_System.collision.enabled
                        && m_System.collision.sendCollisionMessages)
                    {
                        return true;
                    }

                    VividParticleTriggerModule trigger = m_System.trigger;
                    return trigger.enabled
                        && (trigger.inside == VividParticleOverlapAction.Callback
                            || trigger.outside == VividParticleOverlapAction.Callback
                            || trigger.enter == VividParticleOverlapAction.Callback
                            || trigger.exit == VividParticleOverlapAction.Callback);
                }
            }

