            public Material GetOrCreateDefaultMaterial(VividParticleRenderMode renderMode, int renderQueueOffset)
            {
                ParticleMaterialVariantKey key = new(null, renderMode, renderQueueOffset);
                if (m_MaterialVariants.TryGetValue(key, out Material material) && material != null)
                    return material;

                Shader shader = Shader.Find(DefaultShaderName);
                if (shader == null)
                    return null;

                material = new Material(shader)
                {
                    name = $"Vivid Particle System Default Material ({renderMode})",
                    hideFlags = HideFlags.HideAndDontSave,
                };
                ParticleSystemState.ConfigureDefaultParticleMaterial(material);
                ParticleSystemState.ApplyRenderQueueOffset(material, null, renderQueueOffset);
                ParticleSystemState.ConfigureParticleRenderMode(material, renderMode);
                m_MaterialVariants[key] = material;
                return material;
            }

            public Material GetOrCreateMaterialVariant(
                Material sourceMaterial,
                VividParticleRenderMode renderMode,
                int renderQueueOffset)
            {
                if (sourceMaterial == null)
                    return GetOrCreateDefaultMaterial(renderMode, renderQueueOffset);

                ParticleMaterialVariantKey key = new(sourceMaterial, renderMode, renderQueueOffset);
                if (m_MaterialVariants.TryGetValue(key, out Material material) && material != null)
                    return material;

                material = new Material(sourceMaterial)
                {
                    name = $"{sourceMaterial.name} (Vivid Particle Shared Variant)",
                    hideFlags = HideFlags.HideAndDontSave,
                };
                ParticleSystemState.ApplyRenderQueueOffset(material, sourceMaterial, renderQueueOffset);
                ParticleSystemState.ConfigureParticleRenderMode(material, renderMode);
                m_MaterialVariants[key] = material;
                return material;
            }

            public Mesh GetOrCreateBillboardPageMesh()
            {
                if (m_BillboardPageMesh == null)
                    m_BillboardPageMesh = ParticleSystemState.CreateBillboardPageMesh();
                return m_BillboardPageMesh;
            }

            public void UpdateAll(
                NativeArray<VividEcsLineGroupSharedAttachmentRange<VividParticleRendererSharedKey>> groups,
                NativeArray<VividEcsLineGroupAttachment<VividParticleSystemHandle>> systemHandles,
                int matchingLineCount,
                bool forceUpload,
                JobHandle particleDataDependency = default,
                bool hasParticleDataDependency = false)
            {
                m_ParticleDataDependency = particleDataDependency;
                m_HasParticleDataDependency = hasParticleDataDependency;
                BeginBoundsCollection();
                m_HasCollectedBoundsForManagerGraph = false;
                m_LastFallbackBoundsRecordScanCount = 0;
                using (s_UpdateRecordsAndBoundsMarker.Auto())
                {
                    ResetRenderRecordPoolStats();
                    ResetRecordLookupStats();
                    m_LastCombinedUpdateBoundsLineCount = matchingLineCount;
                    s_LastActiveRendererQueryLineCount = matchingLineCount;
                    int handleCount = systemHandles.IsCreated ? systemHandles.Length : 0;
                    s_LastInvalidActiveRendererQueryLineCount = math.max(
                        0,
                        matchingLineCount - handleCount);
                    int groupCount = groups.IsCreated ? groups.Length : 0;
                    for (int groupIndex = 0; groupIndex < groupCount; groupIndex++)
                    {
                        VividEcsLineGroupSharedAttachmentRange<VividParticleRendererSharedKey> group =
                            groups[groupIndex];
                        int handleStart = math.clamp(group.Start, 0, handleCount);
                        int handleEnd = math.clamp(group.Start + group.Count, handleStart, handleCount);
                        if (group.HasSharedComponent == 0
                            || handleStart != group.Start
                            || handleEnd - handleStart != group.Count)
                        {
                            s_LastInvalidActiveRendererQueryLineCount += math.max(0, group.Count);
                            continue;
                        }

                        for (int handleIndex = handleStart; handleIndex < handleEnd; handleIndex++)
                        {
                            if (!TryResolveParticleState(
                                    systemHandles[handleIndex].Value,
                                    out ParticleSystemState state))
                            {
                                s_LastInvalidActiveRendererQueryLineCount++;
                                continue;
                            }

                            UpdateRecord(state, forceUpload);
                            CollectUpdatedBoundsState(state);
                        }
                    }
                }

                ProcessQueuedRecordRemovals();
                if (m_LayoutDirty)
                {
                    m_BoundsPageWorks.Clear();
                    m_BoundsRecordWorks.Clear();
                }
                else
                {
                    m_HasCollectedBoundsForManagerGraph = true;
                }

                ScheduleCollectedBounds();
            }

            public void Update(ParticleSystemState state, bool forceUpload)
            {
                if (state == null)
                    return;

                m_ParticleDataDependency = default;
                m_HasParticleDataDependency = false;
                m_HasCollectedBoundsForManagerGraph = false;
                m_LastFallbackBoundsRecordScanCount = 0;
                using (s_UpdateRecordsMarker.Auto())
                {
                    ResetRenderRecordPoolStats();
                    ResetRecordLookupStats();
                    m_LastCombinedUpdateBoundsLineCount = 0;
                    UpdateRecord(state, forceUpload);
                }

                Commit();
            }

            private void ResetRenderRecordPoolStats()
            {
                m_LastReusedRenderRecordCount = 0;
                m_LastCreatedRenderRecordCount = 0;
            }

            private void ResetRecordLookupStats()
            {
                m_LastHandleRecordLookupCount = 0;
                m_LastManagedRecordFallbackCount = 0;
                m_LastRecordSlotFallbackScanCount = 0;
                m_LastHandleBindingWriteCount = 0;
            }

            private void AssignRendererHandle(
                ParticleSystemState state,
                VividParticleRendererHandle rendererHandle)
            {
                if (state != null && state.SetRendererHandle(rendererHandle))
                    m_LastHandleBindingWriteCount++;
            }

