            private void UpdateRecord(ParticleSystemState state, bool forceUpload)
            {
                bool foundByHandle = TryGetRecordFromHandle(state, out ParticleRenderRecord record);
                if (!foundByHandle)
                {
                    m_LastManagedRecordFallbackCount++;
                    if (TryFindRecordByState(state, out record))
                    {
                        AssignRendererHandle(
                            state,
                            new VividParticleRendererHandle(record.RecordSlot, record.RecordVersion));
                    }
                }
                else
                {
                    m_LastHandleRecordLookupCount++;
                }

                if (record != null
                    && TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord cachedDynamicRecord)
                    && state.TryPrepareCachedRenderDynamicUpdate(forceUpload))
                {
                    record.State = state;
                    state.RefreshRendererDynamicBoundsData(ref cachedDynamicRecord);
                    m_NativeRendererRecords[record.RecordSlot] = cachedDynamicRecord;
                    if (state.HasPendingUploadData())
                        QueueUploadDirty(record);
                    return;
                }

                if (!state.PrepareRenderEntry(forceUpload, out ParticleRenderEntry entry))
                {
                    RemoveRecord(state);
                    return;
                }

                if (record == null)
                {
                    record = AcquireRenderRecord();
                    record.State = state;
                    AllocateRecordSlot(record);
                    SyncNativeRendererRecord(record, entry);
                    state.SetRendererBatchSeed(new ParticleRendererBatchSeed(entry));
                    AssignRendererHandle(
                        state,
                        new VividParticleRendererHandle(record.RecordSlot, record.RecordVersion));
                    QueueUploadDirty(record);
                    m_LayoutDirty = true;
                    return;
                }

                bool hasDynamicRecord = TryGetNativeRendererRecord(
                    record.RecordSlot,
                    record.RecordVersion,
                    out ParticleRendererDynamicRecord previousDynamicRecord);
                bool identityChanged = !hasDynamicRecord
                    || previousDynamicRecord.IdentityVersion != entry.IdentityVersion;
                bool layoutChanged = !hasDynamicRecord
                    || (identityChanged
                        && !previousDynamicRecord.RendererSharedKey.Equals(entry.RendererSharedKey))
                    || previousDynamicRecord.RenderCapacity != entry.Capacity
                    || previousDynamicRecord.SceneCullingMask != entry.SceneCullingMask
                    || previousDynamicRecord.EcsLineId != entry.EcsLineId;
                if (identityChanged)
                    state.SetRendererBatchSeed(new ParticleRendererBatchSeed(entry));
                record.State = state;
                SyncNativeRendererRecord(record, entry);
                if (layoutChanged)
                    m_LayoutDirty = true;

                if (forceUpload || state.HasPendingUploadData())
                    QueueUploadDirty(record);
            }

            public void QueueUploadDirty(ParticleSystemState state)
            {
                if (state == null || !state.rendererHandle.IsValid)
                    return;

                VividParticleRendererHandle handle = state.rendererHandle;
                if (!TryGetNativeRendererRecord(
                        handle.RecordSlot,
                        handle.RecordVersion,
                        out _)
                    || !TryGetNativePendingUploadState(
                        handle.RecordSlot,
                        handle.RecordVersion,
                        out ParticlePendingUploadState pendingState)
                    || !state.TryCapturePendingUploadRequest(
                        forceFullUpload: false,
                        out ParticlePendingUploadRequest request))
                {
                    return;
                }

                if (!request.HasData)
                {
                    state.ClearUploadDirty();
                    pendingState.Request = default;
                    m_NativePendingUploadStates[handle.RecordSlot] = pendingState;
                    return;
                }

                pendingState.Request = request;
                pendingState.Revision = NextUploadRevision(pendingState.Revision);
                if (pendingState.IsQueued == 0)
                {
                    EnsureNativeUploadQueues();
                    m_DirtyUploadRecords.Add(new ParticleUploadRecordRef
                    {
                        RecordSlot = handle.RecordSlot,
                        RecordVersion = handle.RecordVersion,
                    });
                    pendingState.IsQueued = 1;
                }

                m_NativePendingUploadStates[handle.RecordSlot] = pendingState;
            }

            public bool MarkFirstBatchZeroBlockDirtyForTests()
            {
                if (m_DrawBatches.Count == 0)
                    return false;

                ParticleDrawBatch batch = m_DrawBatches[0];
                if (batch == null
                    || !TryGetNativeDrawBatchRecord(
                        batch.BatchIndex,
                        out ParticleNativeDrawBatchRecord nativeBatch))
                    return false;

                nativeBatch.ZeroBlockDirty = 1;
                m_NativeDrawBatchRecords[batch.BatchIndex] = nativeBatch;
                QueueUploadDirty(batch);
                return true;
            }

            public int GetNativeDrawBatchRecordCountForTests()
            {
                return m_NativeDrawBatchRecords.IsCreated
                    ? m_NativeDrawBatchRecords.Length
                    : 0;
            }

            public Vector3[] GetCullingRecordBoundsCentersSnapshot()
            {
                int recordCount = Mathf.Min(
                    m_NativeCullingRecordLength,
                    m_NativeCullingRecords.IsCreated ? m_NativeCullingRecords.Length : 0);
                if (recordCount <= 0)
                    return Array.Empty<Vector3>();

                var centers = new Vector3[recordCount];
                for (int index = 0; index < centers.Length; index++)
                {
                    float3 center = m_NativeCullingRecords[index].BoundsCenter;
                    centers[index] = new Vector3(center.x, center.y, center.z);
                }

                return centers;
            }

            public bool TryGetNativeRendererRecordSnapshot(
                ParticleSystemState state,
                out int activeCount,
                out float4x4 localToWorld,
                out ulong sceneCullingMask,
                out bool isEditorSelected)
            {
                activeCount = 0;
                localToWorld = float4x4.identity;
                sceneCullingMask = 0UL;
                isEditorSelected = false;
                if (state == null
                    || !TryGetRecord(state, out ParticleRenderRecord record)
                    || !TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return false;
                }

                activeCount = dynamicRecord.ActiveCount;
                localToWorld = dynamicRecord.LocalToWorld;
                sceneCullingMask = dynamicRecord.SceneCullingMask;
                isEditorSelected = dynamicRecord.IsEditorSelected != 0;
                return true;
            }

