            public bool SyncCachedBoundsToState(ParticleSystemState state)
            {
                if (state == null
                    || !TryGetRecord(state, out ParticleRenderRecord record)
                    || !TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return false;
                }

                state.RefreshRendererDynamicBoundsData(ref dynamicRecord);
                m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;
                if (dynamicRecord.HasCachedWorldBounds == 0
                    || dynamicRecord.CompletedBoundsVersion != dynamicRecord.BoundsVersion)
                {
                    return false;
                }

                state.ApplyCachedWorldBounds(
                    dynamicRecord.CachedWorldBounds,
                    dynamicRecord.CachedBoundsActiveCount);
                return true;
            }

            public void QueueRemove(ParticleSystemState state)
            {
                if (state == null)
                    return;

                VividParticleRendererHandle handle = state.rendererHandle;
                if (!handle.IsValid
                    || !TryGetNativeRendererRecord(
                        handle.RecordSlot,
                        handle.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord)
                    || dynamicRecord.IsRemoveQueued != 0)
                {
                    return;
                }

                if (!m_RemoveRecordRefs.IsCreated)
                {
                    m_RemoveRecordRefs =
                        new NativeList<ParticleRendererRecordRef>(64, Allocator.Persistent);
                }

                dynamicRecord.IsRemoveQueued = 1;
                m_NativeRendererRecords[handle.RecordSlot] = dynamicRecord;
                m_RemoveRecordRefs.Add(new ParticleRendererRecordRef
                {
                    RecordSlot = handle.RecordSlot,
                    RecordVersion = handle.RecordVersion,
                });
                m_PendingRemoveCount++;
            }

            public void CancelQueuedRemove(ParticleSystemState state)
            {
                if (state == null)
                    return;

                VividParticleRendererHandle handle = state.rendererHandle;
                if (!handle.IsValid
                    || !TryGetNativeRendererRecord(
                        handle.RecordSlot,
                        handle.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord)
                    || dynamicRecord.IsRemoveQueued == 0)
                {
                    return;
                }

                dynamicRecord.IsRemoveQueued = 0;
                m_NativeRendererRecords[handle.RecordSlot] = dynamicRecord;
                m_PendingRemoveCount = Mathf.Max(0, m_PendingRemoveCount - 1);
            }

            private void ProcessQueuedRecordRemovals()
            {
                m_LastRemoveQueueEntryCount = 0;
                m_LastProcessedRemoveCount = 0;
                m_LastCanceledRemoveEntryCount = 0;
                m_LastStaleRemoveEntryCount = 0;
                if (!m_RemoveRecordRefs.IsCreated || m_RemoveRecordRefs.Length == 0)
                    return;

                using (s_RemoveRecordsMarker.Auto())
                {
                    DrainCullingResults();
                    CompletePendingMeshVisibleCountGraph();
                    m_LastRemoveQueueEntryCount = m_RemoveRecordRefs.Length;
                    for (int index = 0; index < m_RemoveRecordRefs.Length; index++)
                    {
                        ParticleRendererRecordRef recordRef = m_RemoveRecordRefs[index];
                        if (!TryGetNativeRendererRecord(
                                recordRef.RecordSlot,
                                recordRef.RecordVersion,
                                out ParticleRendererDynamicRecord dynamicRecord))
                        {
                            m_LastStaleRemoveEntryCount++;
                            continue;
                        }

                        if (dynamicRecord.IsRemoveQueued == 0)
                        {
                            m_LastCanceledRemoveEntryCount++;
                            continue;
                        }

                        dynamicRecord.IsRemoveQueued = 0;
                        m_NativeRendererRecords[recordRef.RecordSlot] = dynamicRecord;
                        if (!TryGetRecord(
                                recordRef.RecordSlot,
                                recordRef.RecordVersion,
                                out ParticleRenderRecord record))
                        {
                            m_LastStaleRemoveEntryCount++;
                            continue;
                        }

                        RemoveRecordCore(record, cancelQueuedRemove: false);
                        m_LastProcessedRemoveCount++;
                    }

                    m_RemoveRecordRefs.Clear();
                    m_PendingRemoveCount = 0;
                }
            }

            private void QueueUploadDirty(ParticleRenderRecord record)
            {
                if (record?.State != null)
                    QueueUploadDirty(record.State);
            }

            private static int NextUploadRevision(int revision)
            {
                unchecked
                {
                    revision++;
                    return revision == 0 ? 1 : revision;
                }
            }

            private void QueueUploadDirty(ParticleDrawBatch batch)
            {
                if (batch == null
                    || !TryGetNativeDrawBatchRecord(
                        batch.BatchIndex,
                        out ParticleNativeDrawBatchRecord nativeBatch)
                    || nativeBatch.UploadDirtyQueued != 0)
                    return;

                EnsureNativeUploadQueues();
                m_DirtyUploadBatchIndices.Add(batch.BatchIndex);
                nativeBatch.UploadDirtyQueued = 1;
                m_NativeDrawBatchRecords[batch.BatchIndex] = nativeBatch;
            }

            private void AllocateRecordSlot(ParticleRenderRecord record)
            {
                int slot;
                if (m_FreeRecordSlots.Count > 0)
                {
                    slot = m_FreeRecordSlots.Pop();
                    m_RecordSlots[slot] = record;
                }
                else
                {
                    slot = m_RecordSlots.Count;
                    m_RecordSlots.Add(record);
                    m_RecordSlotVersions.Add(0);
                }

                record.RecordSlot = slot;
                record.RecordVersion = m_RecordSlotVersions[slot];
                m_ActiveRecordCount++;
            }

            private void EnsureNativeRendererRecordSlotCapacity(int requiredLength)
            {
                requiredLength = Mathf.Max(0, requiredLength);
                if (!m_NativeRendererRecords.IsCreated)
                    m_NativeRendererRecords = new NativeList<ParticleRendererDynamicRecord>(64, Allocator.Persistent);

                if (m_NativeRendererRecords.Length >= requiredLength)
                    return;

                int previousLength = m_NativeRendererRecords.Length;
                m_NativeRendererRecords.ResizeUninitialized(requiredLength);
                for (int index = previousLength; index < requiredLength; index++)
                    m_NativeRendererRecords[index] = default;
            }

            private void EnsureNativePendingUploadStateSlotCapacity(int requiredLength)
            {
                requiredLength = Mathf.Max(0, requiredLength);
                if (!m_NativePendingUploadStates.IsCreated)
                {
                    m_NativePendingUploadStates =
                        new NativeList<ParticlePendingUploadState>(64, Allocator.Persistent);
                }

                if (m_NativePendingUploadStates.Length >= requiredLength)
                    return;

                int previousLength = m_NativePendingUploadStates.Length;
                m_NativePendingUploadStates.ResizeUninitialized(requiredLength);
                for (int index = previousLength; index < requiredLength; index++)
                    m_NativePendingUploadStates[index] = default;
            }

            private void SyncNativeRendererRecord(
                ParticleRenderRecord record,
                ParticleRenderEntry entry)
            {
                if (record == null || record.RecordSlot < 0)
                    return;

                EnsureNativeRendererRecordSlotCapacity(record.RecordSlot + 1);
                EnsureNativePendingUploadStateSlotCapacity(record.RecordSlot + 1);
                if (!TryGetNativePendingUploadState(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticlePendingUploadState pendingUploadState))
                {
                    m_NativePendingUploadStates[record.RecordSlot] = new ParticlePendingUploadState
                    {
                        RecordVersion = record.RecordVersion,
                        IsValid = 1,
                    };
                }
                TryGetNativeRendererRecord(
                    record.RecordSlot,
                    record.RecordVersion,
                    out ParticleRendererDynamicRecord dynamicRecord);
                dynamicRecord.RecordVersion = record.RecordVersion;
                dynamicRecord.IdentityVersion = entry.IdentityVersion;
                dynamicRecord.IsValid = 1;
                dynamicRecord.Layer = Mathf.Clamp(entry.Layer, 0, 31);
                dynamicRecord.IsEditorSelected = entry.IsEditorSelected ? 1 : 0;
                dynamicRecord.RenderMode = (int)entry.RenderMode;
                dynamicRecord.EcsLineId = entry.EcsLineId;
                dynamicRecord.RendererSharedKey = entry.RendererSharedKey;
                dynamicRecord.RenderCapacity = entry.Capacity;
                dynamicRecord.RendererPriority = ResolveRendererPriority(entry.SortingPriority);
                dynamicRecord.BatchLayer = ResolveBatchLayer(entry.BatchLayer);
                dynamicRecord.ShadowCastingMode = (int)entry.ShadowCastingMode;
                dynamicRecord.MotionMode = (int)entry.MotionMode;
                dynamicRecord.ReceiveShadows = entry.ReceiveShadows ? 1 : 0;
                dynamicRecord.StaticShadowCaster = entry.StaticShadowCaster ? 1 : 0;
                dynamicRecord.SortMode = (int)entry.SortMode;
                dynamicRecord.BatchIndex = record.Batch != null ? record.Batch.BatchIndex : -1;
                dynamicRecord.BatchBaseIndex = record.BatchBaseIndex;
                dynamicRecord.SharpIndex = record.SharpIndex;
                dynamicRecord.SpanBaseIndex = record.SpanBaseIndex;
                dynamicRecord.CullingPageBoundsOffset = record.CullingPageBoundsOffset;
                dynamicRecord.CullingPageBoundsCapacity = record.CullingPageBoundsCapacity;
                dynamicRecord.SceneCullingMask = ResolveParticleSceneCullingMask(entry.SceneCullingMask);
                dynamicRecord.PickingEntityId = EntityId.ToULong(entry.PickingEntityId);
                dynamicRecord.RenderingLayerMask = entry.RenderingLayerMask;
                dynamicRecord.SizeScale = entry.SizeScale;
                dynamicRecord.StretchLengthScale = entry.StretchLengthScale;
                dynamicRecord.StretchSpeedScale = entry.StretchSpeedScale;
                dynamicRecord.MinParticleSize = entry.MinParticleSize;
                dynamicRecord.MaxParticleSize = entry.MaxParticleSize;
                dynamicRecord.Pivot = ToFloat3(entry.Pivot);
                dynamicRecord.Flip = ToFloat3(entry.Flip);
                dynamicRecord.RendererColor = ToFloat4(entry.RendererColor);
                dynamicRecord.PerSharpBaseColor = entry.PerSharpBaseColor;
                dynamicRecord.PerSharpScale = entry.PerSharpScale;
                dynamicRecord.PerSharpRotation = entry.PerSharpRotation;
                dynamicRecord.PerSharpVelocityStretch = entry.PerSharpVelocityStretch;
                dynamicRecord.PerSharpCustomData1 = entry.PerSharpCustomData1;
                dynamicRecord.PerSharpCustomData2 = entry.PerSharpCustomData2;
                if (entry.State != null)
                {
                    entry.State.RefreshRendererDynamicBoundsData(ref dynamicRecord);
                }
                else
                {
                    dynamicRecord.ActiveCount = Mathf.Clamp(entry.ActiveCount, 0, entry.Capacity);
                    dynamicRecord.SimulationSpace = (int)entry.SimulationSpace;
                    dynamicRecord.LocalToWorld = ToFloat4x4(entry.LocalToWorldMatrix);
                }
                m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;
            }

            private void SyncNativeRendererLayout(ParticleRenderRecord record)
            {
                if (record == null
                    || !TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return;
                }

                dynamicRecord.BatchIndex = record.Batch != null ? record.Batch.BatchIndex : -1;
                dynamicRecord.BatchBaseIndex = record.BatchBaseIndex;
                dynamicRecord.SharpIndex = record.SharpIndex;
                dynamicRecord.SpanBaseIndex = record.SpanBaseIndex;
                dynamicRecord.CullingRecordStart = -1;
                dynamicRecord.CullingRecordCount = 0;
                dynamicRecord.CullingPageBoundsOffset = record.CullingPageBoundsOffset;
                dynamicRecord.CullingPageBoundsCapacity = record.CullingPageBoundsCapacity;
                m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;
            }

            private bool TryGetNativeRendererRecord(
                int recordSlot,
                int recordVersion,
                out ParticleRendererDynamicRecord dynamicRecord)
            {
                dynamicRecord = default;
                if (!m_NativeRendererRecords.IsCreated
                    || (uint)recordSlot >= (uint)m_NativeRendererRecords.Length)
                {
                    return false;
                }

                dynamicRecord = m_NativeRendererRecords[recordSlot];
                return dynamicRecord.IsValid != 0 && dynamicRecord.RecordVersion == recordVersion;
            }

            private bool TryGetNativePendingUploadState(
                int recordSlot,
                int recordVersion,
                out ParticlePendingUploadState pendingState)
            {
                pendingState = default;
                if (!m_NativePendingUploadStates.IsCreated
                    || (uint)recordSlot >= (uint)m_NativePendingUploadStates.Length)
                {
                    return false;
                }

                pendingState = m_NativePendingUploadStates[recordSlot];
                return pendingState.IsValid != 0 && pendingState.RecordVersion == recordVersion;
            }

            private ParticleRenderRecord AcquireRenderRecord()
            {
                if (m_RecordPool.Count > 0)
                {
                    m_LastReusedRenderRecordCount++;
                    return m_RecordPool.Pop();
                }

                m_LastCreatedRenderRecordCount++;
                return new ParticleRenderRecord();
            }

            private void ReleaseRecordSlot(ParticleRenderRecord record)
            {
                if (record == null)
                    return;

                int slot = record.RecordSlot;
                if ((uint)slot < (uint)m_RecordSlots.Count && m_RecordSlots[slot] == record)
                {
                    m_RecordSlots[slot] = null;
                    m_ActiveRecordCount = Mathf.Max(0, m_ActiveRecordCount - 1);
                    m_RecordSlotVersions[slot]++;
                    if (m_NativeRendererRecords.IsCreated
                        && (uint)slot < (uint)m_NativeRendererRecords.Length)
                    {
                        m_NativeRendererRecords[slot] = new ParticleRendererDynamicRecord
                        {
                            RecordVersion = m_RecordSlotVersions[slot],
                        };
                    }
                    if (m_NativePendingUploadStates.IsCreated
                        && (uint)slot < (uint)m_NativePendingUploadStates.Length)
                    {
                        m_NativePendingUploadStates[slot] = new ParticlePendingUploadState
                        {
                            RecordVersion = m_RecordSlotVersions[slot],
                        };
                    }
                    m_FreeRecordSlots.Push(slot);
                }

                record.RecordSlot = -1;
                record.RecordVersion = 0;
            }

            private void ReleaseRenderRecord(ParticleRenderRecord record)
            {
                if (record == null)
                    return;

                ResetRenderRecordForPool(record);
                m_RecordPool.Push(record);
            }

            private static void ResetRenderRecordForPool(ParticleRenderRecord record)
            {
                record.State = null;
                record.Batch = null;
                record.BatchBaseIndex = 0;
                record.SharpIndex = 0;
                record.SpanBaseIndex = 0;
                record.SpanCapacity = 0;
                record.RecordSlot = -1;
                record.RecordVersion = 0;
                record.CullingPageBoundsOffset = -1;
                record.CullingPageBoundsCapacity = 0;
            }

            private bool TryGetRecord(int recordSlot, int recordVersion, out ParticleRenderRecord record)
            {
                record = null;
                if ((uint)recordSlot >= (uint)m_RecordSlots.Count)
                    return false;

                if (m_RecordSlotVersions[recordSlot] != recordVersion)
                    return false;

                record = m_RecordSlots[recordSlot];
                return record != null;
            }

            private bool TryGetRecordFromHandle(
                ParticleSystemState state,
                out ParticleRenderRecord record)
            {
                record = null;
                if (state == null)
                    return false;

                VividParticleRendererHandle handle = state.rendererHandle;
                return handle.IsValid
                    && TryGetRecord(handle.RecordSlot, handle.RecordVersion, out record)
                    && ReferenceEquals(record.State, state);
            }

            private bool TryGetRecord(
                ParticleSystemState state,
                out ParticleRenderRecord record)
            {
                return TryGetRecordFromHandle(state, out record)
                    || TryFindRecordByState(state, out record);
            }

            private bool TryFindRecordByState(
                ParticleSystemState state,
                out ParticleRenderRecord record)
            {
                record = null;
                if (state == null)
                    return false;

                for (int slot = 0; slot < m_RecordSlots.Count; slot++)
                {
                    m_LastRecordSlotFallbackScanCount++;
                    ParticleRenderRecord candidate = m_RecordSlots[slot];
                    if (candidate != null && ReferenceEquals(candidate.State, state))
                    {
                        record = candidate;
                        return true;
                    }
                }

                return false;
            }

            private void RemoveRecord(ParticleSystemState state)
            {
                if (state == null || !TryGetRecord(state, out ParticleRenderRecord record))
                    return;

                DrainCullingResults();
                CompletePendingMeshVisibleCountGraph();
                RemoveRecordCore(record, cancelQueuedRemove: true);
            }

            private void RemoveRecordCore(
                ParticleRenderRecord record,
                bool cancelQueuedRemove)
            {
                if (record?.State == null)
                    return;

                if (cancelQueuedRemove)
                    CancelQueuedRemove(record.State);
                record.State.SetRendererUploadStats(false, 0, 0, 0, m_GPUBuffer.bufferIndex);
                record.State.ResetRendererCullingStats();
                AssignRendererHandle(record.State, VividParticleRendererHandle.Invalid);
                ReleaseRecordSlot(record);
                ReleaseRenderRecord(record);
                m_LayoutDirty = true;
            }

            private bool RebuildRendererLineGroupsFromEcsQuery()
            {
                m_LastEcsRendererLineGroupCount = 0;
                m_LastEcsRendererLineCount = 0;
                m_LastEcsRendererMatchedLineCount = 0;
                m_LastEcsRendererSkippedLineCount = 0;
                m_LastEcsRendererQueryCreatedCount = 0;
                m_LastEcsRendererQueryReusedCount = 0;
                m_LastEcsRendererQueryCacheBuildCount = 0;
                m_LastEcsRendererQueryCacheHitCount = 0;
                m_LastEcsRendererQuerySourceScanCount = 0;
                m_LastEcsRendererQueryCachedLineCount = 0;
                m_LastEcsRendererLineGroupCacheBuildCount = 0;
                m_LastEcsRendererLineGroupCacheHitCount = 0;
                m_LastEcsRendererLineGroupCacheSourceScanCount = 0;
                m_LastReusedLineGroupCount = 0;
                m_LastCreatedLineGroupCount = 0;

                VividParticleEcsBootstrap.RegisterTypes();
                VividEcsTypeIndex commonTypeIndex = VividEcsTypeManager.GetTypeIndex<VividParticleCommon>();
                VividEcsTypeIndex rendererSharedKeyTypeIndex =
                    VividEcsTypeManager.GetTypeIndex<VividParticleRendererSharedKey>();
                VividEcsTypeIndex rendererActiveTypeIndex =
                    VividEcsTypeManager.GetTypeIndex<VividParticleRendererActive>();
                if (!commonTypeIndex.IsValid
                    || !rendererSharedKeyTypeIndex.IsValid
                    || !rendererActiveTypeIndex.IsValid)
                {
                    return m_DrawBatches.Count > 0;
                }

                VividEcsQuery query = GetOrCreateEcsRendererLineQuery(
                    commonTypeIndex,
                    rendererActiveTypeIndex);
                int previousCacheBuildCount = query.cacheRebuildCount;
                int previousCacheHitCount = query.cacheHitCount;
                VividEcsArchetypeLineGroupCache lineGroupCache =
                    GetOrCreateEcsRendererLineGroupCache(query, rendererSharedKeyTypeIndex);
                int previousGroupCacheBuildCount = lineGroupCache.cacheRebuildCount;
                int previousGroupCacheHitCount = lineGroupCache.cacheHitCount;
                bool groupCacheRebuilt = lineGroupCache.Prepare();
                VividEcsArchetypeLineGroupNativeSharedAttachmentCache<
                    VividParticleRendererSharedKey,
                    VividParticleRendererHandle>
                    handleGroupCache = GetOrCreateEcsRendererHandleGroupCache(lineGroupCache);
                bool handleCacheRebuilt = handleGroupCache.Prepare(groupCacheRebuilt);
                m_LastEcsRendererQueryCacheBuildCount = query.cacheRebuildCount - previousCacheBuildCount;
                m_LastEcsRendererQueryCacheHitCount = query.cacheHitCount - previousCacheHitCount;
                m_LastEcsRendererQuerySourceScanCount = query.lastSourceScanCount;
                m_LastEcsRendererQueryCachedLineCount = query.cachedMatchingLineCount;
                m_LastEcsRendererLineGroupCacheBuildCount =
                    lineGroupCache.cacheRebuildCount - previousGroupCacheBuildCount;
                m_LastEcsRendererLineGroupCacheHitCount =
                    lineGroupCache.cacheHitCount - previousGroupCacheHitCount;
                m_LastEcsRendererLineGroupCacheSourceScanCount = lineGroupCache.lastSourceLineScanCount;
                m_LastEcsRendererLineGroupCount = lineGroupCache.groupCount;

                bool reuseDrawBatchMembership = !groupCacheRebuilt
                    && !handleCacheRebuilt
                    && m_DrawBatches.Count == lineGroupCache.groupCount;
                if (reuseDrawBatchMembership)
                {
                    for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                        m_LastEcsRendererLineCount += m_DrawBatches[batchIndex].RecordRefCount;
                    m_LastEcsRendererMatchedLineCount = m_LastEcsRendererLineCount;
                    m_LastReusedLineGroupCount = lineGroupCache.groupCount;
                    return false;
                }

                m_LastEcsRendererLineCount = handleGroupCache.attachmentCount;
                m_LastCreatedLineGroupCount = lineGroupCache.groupCount;
                return true;
            }

            private void BuildDrawBatchesFromEcsGroups()
            {
                NativeArray<VividEcsLineGroupSharedAttachmentRange<VividParticleRendererSharedKey>> groups =
                    m_EcsRendererHandleGroupCache?.groups ?? default;
                NativeArray<VividEcsLineGroupAttachment<VividParticleRendererHandle>> attachments =
                    m_EcsRendererHandleGroupCache?.attachments ?? default;
                if (!groups.IsCreated || !attachments.IsCreated)
                    return;

                EnsureNativeCullingLayout();
                m_EcsBatchRecordRefs.Clear();
                m_LastBatchSeedAttachmentLookupCount = 0;
                m_LastManagedBatchSeedFallbackCount = 0;

                for (int groupIndex = 0; groupIndex < groups.Length; groupIndex++)
                {
                    VividEcsLineGroupSharedAttachmentRange<VividParticleRendererSharedKey> group =
                        groups[groupIndex];
                    if (group.GroupIndex != groupIndex
                        || group.HasSharedComponent == 0
                        || group.Count == 0)
                    {
                        m_LastEcsRendererSkippedLineCount += group.Count;
                        continue;
                    }

                    VividParticleRendererSharedKey groupKey = group.SharedComponent;
                    if (groupKey.Equals(VividParticleRendererSharedKey.Invalid)
                        || group.Start < 0
                        || group.Start + group.Count > attachments.Length)
                    {
                        m_LastEcsRendererSkippedLineCount += group.Count;
                        continue;
                    }

                    ParticleDrawBatch batch = null;
                    int attachmentEnd = group.Start + group.Count;
                    for (int attachmentIndex = group.Start;
                         attachmentIndex < attachmentEnd;
                         attachmentIndex++)
                    {
                        VividEcsLineGroupAttachment<VividParticleRendererHandle> attachment =
                            attachments[attachmentIndex];
                        VividParticleRendererHandle rendererHandle = attachment.Value;
                        if (!rendererHandle.IsValid
                            || !TryGetNativeRendererRecord(
                                rendererHandle.RecordSlot,
                                rendererHandle.RecordVersion,
                                out ParticleRendererDynamicRecord dynamicRecord)
                            || !dynamicRecord.RendererSharedKey.Equals(groupKey))
                        {
                            m_LastEcsRendererSkippedLineCount++;
                            continue;
                        }

                        if (batch == null)
                        {
                            if (!TryResolveBatchSeed(
                                    attachment.LineId,
                                    rendererHandle,
                                    out ParticleRendererBatchSeed seed))
                            {
                                m_LastEcsRendererSkippedLineCount++;
                                continue;
                            }

                            batch = AcquireDrawBatch(seed, groupKey);
                            batch.RecordRefStart = m_EcsBatchRecordRefs.Length;
                        }

                        m_EcsBatchRecordRefs.Add(new ParticleRendererRecordRef
                        {
                            RecordSlot = rendererHandle.RecordSlot,
                            RecordVersion = rendererHandle.RecordVersion,
                        });
                        batch.RecordRefCount++;
                        m_LastEcsRendererMatchedLineCount++;
                    }

                    if (batch == null)
                        continue;

                    batch.BatchIndex = m_DrawBatches.Count;
                    m_DrawBatches.Add(batch);
                }
            }

            private bool TryResolveBatchSeed(
                int lineId,
                VividParticleRendererHandle rendererHandle,
                out ParticleRendererBatchSeed seed)
            {
                if (s_ParticleEcsWorld.TryGetLineAttachment(lineId, out seed))
                {
                    m_LastBatchSeedAttachmentLookupCount++;
                    return true;
                }

                m_LastManagedBatchSeedFallbackCount++;
                if (TryGetRecord(
                        rendererHandle.RecordSlot,
                        rendererHandle.RecordVersion,
                        out ParticleRenderRecord record)
                    && record.State != null
                    && record.State.PrepareRenderEntry(
                        forceUpload: false,
                        out ParticleRenderEntry entry))
                {
                    seed = new ParticleRendererBatchSeed(entry);
                    record.State.SetRendererBatchSeed(seed);
                    return true;
                }

                seed = default;
                return false;
            }

            private VividEcsQuery GetOrCreateEcsRendererLineQuery(
                VividEcsTypeIndex commonTypeIndex,
                VividEcsTypeIndex rendererActiveTypeIndex)
            {
                if (m_EcsRendererLineQuery == null
                    || m_EcsRendererLineQueryCommonTypeIndex != commonTypeIndex
                    || m_EcsRendererLineQueryActiveTypeIndex != rendererActiveTypeIndex)
                {
                    m_EcsRendererLineQuery = s_ParticleEcsWorld.CreateQuery()
                        .WithAll(commonTypeIndex, rendererActiveTypeIndex);
                    m_EcsRendererLineQueryCommonTypeIndex = commonTypeIndex;
                    m_EcsRendererLineQueryActiveTypeIndex = rendererActiveTypeIndex;
                    m_LastEcsRendererQueryCreatedCount++;
                    return m_EcsRendererLineQuery;
                }

                m_LastEcsRendererQueryReusedCount++;
                return m_EcsRendererLineQuery;
            }

            private void ClearDrawBatches()
            {
                for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                    ReleaseDrawBatch(m_DrawBatches[batchIndex]);

                m_DrawBatches.Clear();
            }

            private void DisposeAllDrawBatches()
            {
                for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                    DisposeDrawBatch(m_DrawBatches[batchIndex]);

                m_DrawBatches.Clear();

                while (m_DrawBatchPool.Count > 0)
                    DisposeDrawBatch(m_DrawBatchPool.Pop());
            }

            private void ReleaseDrawBatch(ParticleDrawBatch batch)
            {
                if (batch == null)
                    return;

                ResetDrawBatchForPool(batch);
                m_DrawBatchPool.Push(batch);
            }

            private void ResetDrawBatchForPool(ParticleDrawBatch batch)
            {
                if (batch == null)
                    return;

                for (int recordIndex = 0; recordIndex < batch.RecordRefCount; recordIndex++)
                {
                    ParticleRendererRecordRef recordRef =
                        m_EcsBatchRecordRefs[batch.RecordRefStart + recordIndex];
                    if (TryGetRecord(
                            recordRef.RecordSlot,
                            recordRef.RecordVersion,
                            out ParticleRenderRecord record)
                        && record.Batch == batch)
                    {
                        record.Batch = null;
                    }
                }

                batch.RecordRefStart = -1;
                batch.RecordRefCount = 0;
                batch.Key = default;
                batch.Material = null;
                batch.Mesh = null;
                batch.Meshes = Array.Empty<Mesh>();
                batch.MeshCount = 0;
                batch.BatchId = BatchID.Null;
                batch.MeshId = BatchMeshID.Null;
                batch.MaterialId = default;
                batch.ShadowCastingMode = ShadowCastingMode.Off;
                batch.MotionMode = MotionVectorGenerationMode.ForceNoMotion;
                batch.ReceiveShadows = false;
                batch.StaticShadowCaster = false;
                batch.SortingPriority = 0;
                batch.BatchLayer = 0;
                batch.UsesPageBillboard = false;
                batch.RequiresSortingPositions = false;
                batch.GpuLayout = default;
                if (batch.GpuBufferInfos.IsCreated)
                    batch.GpuBufferInfos.Clear();
                batch.SharedDataBufferInfo = default;
                batch.SpanSharedDataBufferInfo = default;
                batch.UploadColumnLayout = default;
                batch.HasSharedDataBufferInfo = false;
                batch.HasSpanSharedDataBufferInfo = false;
                batch.CullingMeshIdOffset = -1;
                batch.BatchIndex = -1;
                batch.Capacity = 0;
                batch.SharpCapacity = 0;
                batch.SpanCapacity = 0;
                batch.DataOffset = 0;
            }

            private static void DisposeDrawBatch(ParticleDrawBatch batch)
            {
                if (batch == null)
                    return;

                if (batch.GpuBufferInfos.IsCreated)
                    batch.GpuBufferInfos.Dispose();

            }

            public void Commit()
            {
                try
                {
                    using (s_CommitMarker.Auto())
                    {
                        if (m_LayoutDirty)
                        {
                            CompletePendingBoundsUpdates();
                            RebuildBatches();
                        }

                        CompletePendingBoundsUpdates();
                        ScheduleManagerJobGraph();
                        RebuildNativeCullingLayout();
                    }
                }
                finally
                {
                    m_ParticleDataDependency = default;
                    m_HasParticleDataDependency = false;
                }
            }

            private void ScheduleManagerJobGraph()
            {
                using (s_ManagerJobGraphScheduleMarker.Auto())
                {
                    ScheduleRenderUploadGraph();
                    if (!m_HasPendingBounds && !m_HasCollectedBoundsForManagerGraph)
                        ScheduleBoundsUpdatesFromRecords();
                    m_HasCollectedBoundsForManagerGraph = false;
                    CompletePendingBoundsUpdates();
                    ScheduleMeshVisibleCountGraph();
                }
            }

            private void BeginBoundsCollection()
            {
                CompletePendingBoundsUpdates();
                EnsureNativeBoundsLayout();
                m_BoundsPageWorks.Clear();
                m_BoundsRecordWorks.Clear();
                m_BoundsRequiredPageCapacity = m_CullingPageBoundsCount;
            }

            private void ScheduleBoundsUpdatesFromRecords()
            {
                BeginBoundsCollection();
                m_LastFallbackBoundsRecordScanCount = m_RendererRecordRefs.IsCreated
                    ? m_RendererRecordRefs.Length
                    : 0;

                using (s_BoundsCollectMarker.Auto())
                {
                    if (m_RendererRecordRefs.IsCreated)
                    {
                        for (int recordIndex = 0; recordIndex < m_RendererRecordRefs.Length; recordIndex++)
                        {
                            ParticleRendererRecordRef recordRef = m_RendererRecordRefs[recordIndex];
                            if (TryGetRecord(
                                    recordRef.RecordSlot,
                                    recordRef.RecordVersion,
                                    out ParticleRenderRecord record)
                                && TryGetNativeRendererRecord(
                                    recordRef.RecordSlot,
                                    recordRef.RecordVersion,
                                    out ParticleRendererDynamicRecord dynamicRecord))
                            {
                                CollectBoundsState(record, dynamicRecord);
                            }
                        }
                    }
                }

                ScheduleCollectedBounds();
            }

            private void CollectUpdatedBoundsState(ParticleSystemState state)
            {
                if (state == null
                    || !TryGetRecord(state, out ParticleRenderRecord record)
                    || !TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return;
                }

                CollectBoundsState(record, dynamicRecord);
            }

            private void CollectBoundsState(ParticleSystemState state)
            {
                if (state == null
                    || !TryGetRecord(state, out ParticleRenderRecord record)
                    || !TryGetNativeRendererRecord(
                        record.RecordSlot,
                        record.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return;
                }

                state.RefreshRendererDynamicBoundsData(ref dynamicRecord);
                m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;

                CollectBoundsState(record, dynamicRecord);
            }

            private void CollectBoundsState(
                ParticleRenderRecord record,
                ParticleRendererDynamicRecord dynamicRecord)
            {
                if (record == null || dynamicRecord.IsRenderable == 0)
                    return;

                int count = Mathf.Clamp(
                    dynamicRecord.ActiveCount,
                    0,
                    Mathf.Max(0, dynamicRecord.StorageCapacity));
                if (dynamicRecord.HasCachedWorldBounds != 0
                    && dynamicRecord.CompletedBoundsVersion == dynamicRecord.BoundsVersion
                    && dynamicRecord.CachedBoundsActiveCount == count)
                {
                    return;
                }

                ParticleBoundsSource source = dynamicRecord.BoundsSource;
                if (count <= 0 || source.Positions == null)
                {
                    dynamicRecord.CachedWorldBounds = default;
                    dynamicRecord.CachedBoundsActiveCount = count;
                    dynamicRecord.HasCachedWorldBounds = 1;
                    dynamicRecord.CompletedBoundsVersion = dynamicRecord.BoundsVersion;
                    m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;
                    return;
                }

                int pageCount = Mathf.Max(1, GetCullingRecordCount(count));
                int pageStart;
                if (dynamicRecord.CullingPageBoundsOffset >= 0
                    && dynamicRecord.CullingPageBoundsCapacity >= pageCount)
                {
                    pageStart = dynamicRecord.CullingPageBoundsOffset;
                }
                else
                {
                    pageStart = m_BoundsRequiredPageCapacity;
                }

                m_BoundsRequiredPageCapacity = Mathf.Max(m_BoundsRequiredPageCapacity, pageStart + pageCount);
                for (int pageIndex = 0; pageIndex < pageCount; pageIndex++)
                {
                    int particleStart = pageIndex * BillboardPageSize;
                    int particleCount = Mathf.Clamp(count - particleStart, 0, BillboardPageSize);
                    m_BoundsPageWorks.Add(new ParticleBoundsPageWork
                    {
                        Page = new VividEcsPageInfo(
                            dynamicRecord.EcsLineId,
                            pageIndex,
                            particleStart,
                            particleCount),
                        Source = source,
                        ResultIndex = pageStart + pageIndex,
                    });
                }

                m_BoundsRecordWorks.Add(new ParticleBoundsRecordReduceWork
                {
                    RecordSlot = record.RecordSlot,
                    RecordVersion = record.RecordVersion,
                    BoundsVersion = dynamicRecord.BoundsVersion,
                    PageStart = pageStart,
                    PageCount = pageCount,
                    ActiveCount = count,
                    UsesPageBillboard = UsesPageBillboardRenderMode(
                        (VividParticleRenderMode)dynamicRecord.RenderMode) ? 1 : 0,
                });
            }

            private void ScheduleCollectedBounds()
            {
                if (m_BoundsPageWorks.Length <= 0 || m_BoundsRecordWorks.Length <= 0)
                {
                    m_LastBoundsPageWorkCount = 0;
                    m_LastBoundsRecordWorkCount = 0;
                    return;
                }

                EnsureBoundsResultCapacity(m_BoundsRequiredPageCapacity, m_BoundsRecordWorks.Length);
                m_LastBoundsPageWorkCount = m_BoundsPageWorks.Length;
                m_LastBoundsRecordWorkCount = m_BoundsRecordWorks.Length;

                using (s_BoundsScheduleMarker.Auto())
                {
                    var pageJob = new ParticleBoundsBatchPageJob
                    {
                        Works = m_BoundsPageWorks.AsArray(),
                        PageBounds = m_BoundsPageResults,
                    };
                    JobHandle pageDependency = m_HasPendingCullingRecordBuild
                        ? m_PendingCullingRecordBuildHandle
                        : default;
                    if (m_HasParticleDataDependency)
                    {
                        pageDependency = m_HasPendingCullingRecordBuild
                            ? JobHandle.CombineDependencies(
                                pageDependency,
                                m_ParticleDataDependency)
                            : m_ParticleDataDependency;
                    }
                    JobHandle pageHandle = pageJob.ScheduleParallelEmbedded(
                        m_BoundsPageWorks.AsArray(),
                        pageInfoByteOffset: 0,
                        dependency: pageDependency,
                        innerloopBatchCount: 1,
                        dispatchMode: VividEcsPageDispatchMode.Average);

                    var reduceJob = new ParticleBoundsBatchReduceJob
                    {
                        Works = m_BoundsRecordWorks.AsArray(),
                        PageBounds = m_BoundsPageResults,
                        RecordResults = m_BoundsRecordResults,
                    };

                    m_PendingBoundsHandle = reduceJob.Schedule(m_BoundsRecordWorks.Length, innerloopBatchCount: 1, pageHandle);
                    m_HasPendingBounds = true;
                    JobHandle.ScheduleBatchedJobs();
                }
            }

            public void CompletePendingBoundsUpdates()
            {
                if (!m_HasPendingBounds)
                    return;

                using (s_BoundsCompleteMarker.Auto())
                {
                    m_PendingBoundsHandle.Complete();
                    m_PendingBoundsHandle = default;
                    m_HasPendingBounds = false;

                    int resultCount = Mathf.Min(
                        m_BoundsRecordWorks.IsCreated ? m_BoundsRecordWorks.Length : 0,
                        m_BoundsRecordResults.IsCreated ? m_BoundsRecordResults.Length : 0);
                    for (int recordIndex = 0; recordIndex < resultCount; recordIndex++)
                    {
                        ParticleBoundsRecordResult result = m_BoundsRecordResults[recordIndex];
                        if (!TryGetNativeRendererRecord(
                                result.RecordSlot,
                                result.RecordVersion,
                                out ParticleRendererDynamicRecord dynamicRecord)
                            || dynamicRecord.BoundsVersion != result.BoundsVersion)
                        {
                            continue;
                        }

                        dynamicRecord.CachedWorldBounds = result.WorldBounds;
                        dynamicRecord.CachedBoundsActiveCount = result.ActiveCount;
                        dynamicRecord.HasCachedWorldBounds = 1;
                        dynamicRecord.CompletedBoundsVersion = result.BoundsVersion;
                        m_NativeRendererRecords[result.RecordSlot] = dynamicRecord;
                    }

                    m_BoundsPageWorks.Clear();
                    m_BoundsRecordWorks.Clear();
                    m_BoundsRequiredPageCapacity = m_CullingPageBoundsCount;
                }
            }

            private unsafe void RebuildNativeCullingLayout()
            {
                using (s_RebuildCullingLayoutMarker.Auto())
                {
                    DrainCullingResults();
                    EnsureNativeCullingLayout();
                    m_NativeCullingRecords.Clear();
                    m_NativeCullingRecordLength = 0;
                    m_NativeDrawCommandInputs.Clear();
                    m_NativeDrawRangeInputs.Clear();
                    m_NativeLightDrawCommandInputs.Clear();
                    m_NativeLightDrawRangeInputs.Clear();
                    m_NativePickingDrawCommandInputs.Clear();
                    m_NativePickingDrawRangeInputs.Clear();
                    m_NativeSelectionDrawCommandInputs.Clear();
                    m_NativeSelectionDrawRangeInputs.Clear();
                    m_CullingRecordBuildWorks.Clear();
                    m_PickingDrawBuildWorks.Clear();
                    m_BatchDrawBuildWorks.Clear();
                    m_PickingDrawBuildResult[0] = default;
                    m_BatchDrawBuildResult[0] = default;
                    m_PickingDrawBuildCommandCapacity = 0;
                    m_BatchDrawBuildCommandCapacity = 0;
                    m_NativeVisibleInstanceCapacity = 0;
                    m_NativeSortingPositionCapacity = 0;
                    m_NativeLightVisibleInstanceCapacity = 0;
                    m_NativePickingVisibleInstanceCapacity = 0;
                    m_NativeSelectionVisibleInstanceCapacity = 0;
                    m_AnyShadowCastingBatch = false;
                    m_AnySelectedRecord = false;
                    m_NativeDrawCommandLayerMask = 0u;
                    m_NativeLightDrawCommandLayerMask = 0u;
                    m_NativePickingDrawCommandLayerMask = 0u;
                    m_NativeSelectionDrawCommandLayerMask = 0u;
                    m_NativeDrawCommandSceneCullingMask = 0UL;
                    m_NativeLightDrawCommandSceneCullingMask = 0UL;
                    m_NativePickingDrawCommandSceneCullingMask = 0UL;
                    m_NativeSelectionDrawCommandSceneCullingMask = 0UL;
                    m_LastCullingSingleMeshCacheRecordCount = 0;
                    m_LastCullingMultiMeshCacheRecordCount = 0;
                    m_LastCullingMeshFallbackRecordCount = 0;
                    m_LastCullingRecordVisibleCacheEntryCount = 0;
                    m_LastCullingBatchVisibleCacheEntryCount = 0;
                    m_LastCullingRecordBuildWorkCount = 0;
                    m_LastVisibleInstanceCapacityCacheEntryCount = 0;
                    m_LastPickingDrawBuildWorkCount = 0;
                    m_LastBatchDrawBuildWorkCount = 0;
                    m_LastCullingCollectScheduledRecordCount = 0;
                    m_LastCullingCollectValidRecordCount = 0;

                    JobHandle cullingCollectHandle;
                    NativeArray<ParticlePickingDrawBuildWork> pickingDrawBuildWorks;
                    NativeArray<ParticleBatchDrawBuildWork> batchDrawBuildWorks;
                    using (s_CullingLayoutCollectMarker.Auto())
                    {
                        cullingCollectHandle = CollectCullingRecordsAndMeshCountWorks(
                            m_HasPendingMeshVisibleCount
                                ? m_PendingMeshVisibleCountHandle
                                : default,
                            m_MeshVisibleRendererRecordRefsView,
                            m_MeshVisibleRendererRecordsView,
                            m_MeshVisibleDrawBatchesView,
                            m_MeshVisibleRecordCountRefsView,
                            out pickingDrawBuildWorks,
                            out batchDrawBuildWorks);
                    }

                    using (s_CullingLayoutDrawCommandsMarker.Auto())
                    {
                        BuildDrawCommandsFromCullingRecords(
                            cullingCollectHandle,
                            pickingDrawBuildWorks,
                            batchDrawBuildWorks);
                    }

                    using (s_CullingLayoutCacheMarker.Auto())
                    {
                        m_LastCullingMultiMeshCacheRecordCount =
                            m_LastMeshVisibleCountWorkCount;
                    }
                }
            }

            private VividEcsArchetypeLineGroupCache GetOrCreateEcsRendererLineGroupCache(
                VividEcsQuery query,
                VividEcsTypeIndex rendererSharedKeyTypeIndex)
            {
                if (m_EcsRendererLineGroupCache == null
                    || !m_EcsRendererLineGroupCache.Matches(query, rendererSharedKeyTypeIndex))
                {
                    m_EcsRendererLineGroupCache = new VividEcsArchetypeLineGroupCache(
                        query,
                        rendererSharedKeyTypeIndex);
                }

                return m_EcsRendererLineGroupCache;
            }

            private VividEcsArchetypeLineGroupNativeSharedAttachmentCache<
                VividParticleRendererSharedKey,
                VividParticleRendererHandle>
                GetOrCreateEcsRendererHandleGroupCache(
                    VividEcsArchetypeLineGroupCache lineGroupCache)
            {
                if (m_EcsRendererHandleGroupCache == null
                    || !m_EcsRendererHandleGroupCache.Matches(
                        s_ParticleEcsWorld,
                        lineGroupCache))
                {
                    m_EcsRendererHandleGroupCache?.Dispose();
                    m_EcsRendererHandleGroupCache =
                        new VividEcsArchetypeLineGroupNativeSharedAttachmentCache<
                            VividParticleRendererSharedKey,
                            VividParticleRendererHandle>(
                            s_ParticleEcsWorld,
                            lineGroupCache);
                }

                return m_EcsRendererHandleGroupCache;
            }

            private void RebuildCullingBatchMeshIds()
            {
                m_CullingBatchMeshIds.Clear();
                for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                {
                    ParticleDrawBatch batch = m_DrawBatches[batchIndex];
                    batch.CullingMeshIdOffset = m_CullingBatchMeshIds.Length;
                    int meshCommandCount = GetBatchDrawMeshCommandCount(batch);
                    for (int meshCommandIndex = 0; meshCommandIndex < meshCommandCount; meshCommandIndex++)
                    {
                        int meshIndexFilter = ResolveMeshIndexFilter(batch, meshCommandIndex);
                        m_CullingBatchMeshIds.Add(GetBatchMeshId(batch, meshIndexFilter));
                    }
                }
            }

            private unsafe JobHandle CollectCullingRecordsAndMeshCountWorks(
                JobHandle dependency,
                NativeArray<ParticleRendererRecordRef> rendererRecordRefs,
                NativeArray<ParticleRendererDynamicRecord> rendererRecords,
                NativeArray<ParticleNativeDrawBatchRecord> drawBatches,
                NativeArray<ParticleMeshVisibleRecordCountRef> meshVisibleRecordCountRefs,
                out NativeArray<ParticlePickingDrawBuildWork> pickingDrawBuildWorks,
                out NativeArray<ParticleBatchDrawBuildWork> batchDrawBuildWorks)
            {
                int rendererRecordRefCount = rendererRecordRefs.IsCreated
                    ? rendererRecordRefs.Length
                    : 0;
                m_LastCullingCollectScheduledRecordCount = rendererRecordRefCount;
                m_CullingRecordBuildWorks.ResizeUninitialized(rendererRecordRefCount);
                m_PickingDrawBuildWorks.ResizeUninitialized(rendererRecordRefCount);
                int drawBatchCount = drawBatches.IsCreated
                    ? drawBatches.Length
                    : 0;
                m_BatchDrawBuildWorks.ResizeUninitialized(drawBatchCount);
                NativeArray<ParticleCullingRecordBuildWork> cullingRecordBuildWorks =
                    m_CullingRecordBuildWorks.AsArray();
                pickingDrawBuildWorks = m_PickingDrawBuildWorks.AsArray();
                batchDrawBuildWorks = m_BatchDrawBuildWorks.AsArray();
                m_CullingLayoutCollectResult[0] = default;
                if (rendererRecordRefCount <= 0 && drawBatchCount <= 0)
                    return default;

                JobHandle collectHandle;
                using (s_CullingLayoutCollectScheduleMarker.Auto())
                {
                    collectHandle = new ParticleCullingLayoutCollectJob
                    {
                        RecordRefs = rendererRecordRefs,
                        RendererRecords = rendererRecords,
                        DrawBatches = drawBatches,
                        MeshVisibleRecordCountRefs = meshVisibleRecordCountRefs,
                        CullingWorks = cullingRecordBuildWorks,
                        PickingWorks = pickingDrawBuildWorks,
                        BatchWorks = batchDrawBuildWorks,
                        Result = m_CullingLayoutCollectResult,
                    }.Schedule(dependency);
                    JobHandle.ScheduleBatchedJobs();
                }

                int cullingRecordCapacity = Mathf.Max(0, m_CullingPageBoundsCount);
                m_NativeCullingRecords.ResizeUninitialized(cullingRecordCapacity);
                m_NativeCullingRecordLength = 0;
                if (rendererRecordRefCount > 0 && cullingRecordCapacity > 0)
                {
                    using (s_CullingLayoutRecordBuildScheduleMarker.Auto())
                    {
                        m_PendingCullingRecordBuildHandle = new ParticleCullingRecordBuildJob
                        {
                            Works = cullingRecordBuildWorks,
                            PageBounds = m_BoundsPageResults,
                            Records = m_NativeCullingRecords.AsArray(),
                        }.Schedule(
                            rendererRecordRefCount,
                            innerloopBatchCount: 1,
                            collectHandle);
                        m_HasPendingCullingRecordBuild = true;
                        JobHandle.ScheduleBatchedJobs();
                    }
                }

                return collectHandle;
            }

            internal static unsafe bool TryCreateCullingRecordBuildWork(
                ParticleRendererDynamicRecord dynamicRecord,
                int outputOffset,
                bool usesPageBillboard,
                out ParticleCullingRecordBuildWork work)
            {
                work = default;
                int count = Mathf.Clamp(
                    dynamicRecord.ActiveCount,
                    0,
                    Mathf.Max(0, dynamicRecord.StorageCapacity));
                int pageCount = Mathf.Min(
                    GetCullingRecordCount(count),
                    Mathf.Max(0, dynamicRecord.CullingPageBoundsCapacity));
                if (dynamicRecord.IsRenderable == 0
                    || count <= 0
                    || dynamicRecord.CullingPageBoundsOffset < 0
                    || pageCount <= 0)
                {
                    return false;
                }

                work = new ParticleCullingRecordBuildWork
                {
                    PageBoundsOffset = dynamicRecord.CullingPageBoundsOffset,
                    OutputOffset = Mathf.Max(0, outputOffset),
                    PageCount = pageCount,
                    BatchBaseIndex = Mathf.Max(0, dynamicRecord.BatchBaseIndex),
                    SpanBaseIndex = Mathf.Max(0, dynamicRecord.SpanBaseIndex),
                    ActiveCount = count,
                    UsesPageBillboard = usesPageBillboard ? 1 : 0,
                    IsEditorSelected = dynamicRecord.IsEditorSelected,
                    SceneCullingMask = ResolveParticleSceneCullingMask(dynamicRecord.SceneCullingMask),
                    MeshIndices = dynamicRecord.MeshIndices,
                    Positions = usesPageBillboard ? null : dynamicRecord.Positions,
                    PositionCapacity = usesPageBillboard ? 0 : dynamicRecord.StorageCapacity,
                    LocalToWorld = dynamicRecord.LocalToWorld,
                    SimulationSpace = dynamicRecord.SimulationSpace,
                    FallbackBoundsCenter = dynamicRecord.LocalToWorld.c3.xyz,
                };
                return true;
            }

            internal static unsafe bool TryCreateMeshVisibleCountWork(
                ParticleRendererDynamicRecord dynamicRecord,
                VividParticleRenderMode renderMode,
                int meshCount,
                int outputOffset,
                out ParticleMeshVisibleCountWork work)
            {
                work = default;
                int count = Mathf.Clamp(
                    dynamicRecord.ActiveCount,
                    0,
                    Mathf.Max(0, dynamicRecord.StorageCapacity));
                if (dynamicRecord.IsRenderable == 0
                    || renderMode != VividParticleRenderMode.Mesh
                    || meshCount <= 1
                    || count <= 0)
                {
                    return false;
                }

                work = new ParticleMeshVisibleCountWork
                {
                    IsValid = 1,
                    MeshIndices = dynamicRecord.MeshIndices,
                    ActiveCount = count,
                    MeshCount = Mathf.Max(1, meshCount),
                    OutputOffset = Mathf.Max(0, outputOffset),
                };
                return true;
            }

            internal static int ResetBatchCullingCache(
                ref ParticleNativeDrawBatchRecord nativeBatch,
                int meshCommandCount)
            {
                if (nativeBatch.IsValid == 0)
                    return 0;

                nativeBatch.CullingRecordStart = -1;
                nativeBatch.CullingRecordCount = 0;
                nativeBatch.SingleMeshVisibleCapacity = 0;
                return meshCommandCount <= 1 ? 1 : 0;
            }

            internal static void AddBatchCullingRecordRange(
                ref ParticleNativeDrawBatchRecord nativeBatch,
                int recordStart,
                int recordCount)
            {
                if (nativeBatch.IsValid == 0 || recordCount <= 0)
                    return;

                if (nativeBatch.CullingRecordStart < 0)
                {
                    nativeBatch.CullingRecordStart = recordStart;
                    nativeBatch.CullingRecordCount = recordCount;
                    return;
                }

                int currentEnd = nativeBatch.CullingRecordStart + nativeBatch.CullingRecordCount;
                int nextEnd = recordStart + recordCount;
                int mergedStart = Mathf.Min(nativeBatch.CullingRecordStart, recordStart);
                int mergedEnd = Mathf.Max(currentEnd, nextEnd);
                nativeBatch.CullingRecordStart = mergedStart;
                nativeBatch.CullingRecordCount = Mathf.Max(0, mergedEnd - mergedStart);
            }

            private void ScheduleMeshVisibleCountGraph()
            {
                CompletePendingMeshVisibleCountGraph();
                EnsureNativeCullingLayout();
                int rendererRecordRefCount = m_RendererRecordRefs.IsCreated
                    ? m_RendererRecordRefs.Length
                    : 0;
                int drawBatchCount = m_NativeDrawBatchRecords.IsCreated
                    ? m_NativeDrawBatchRecords.Length
                    : 0;
                m_MeshVisibleCountWorks.ResizeUninitialized(rendererRecordRefCount);
                m_MeshVisibleRecordCountRefs.ResizeUninitialized(rendererRecordRefCount);
                m_MeshVisibleBatchReduceWorks.ResizeUninitialized(drawBatchCount);
                m_MeshVisibleCountLength = 0;
                m_MeshBatchVisibleCountLength = 0;
                m_LastMeshVisibleCountWorkCount = 0;
                m_LastMeshVisibleCountInlineWorkCount = 0;
                m_LastMeshVisibleCountScheduledWorkCount = 0;
                m_LastMeshVisibleBatchReduceWorkCount = 0;
                m_MeshVisibleCollectResult[0] = default;
                m_MeshVisibleRendererRecordRefsView = m_RendererRecordRefs.AsArray();
                m_MeshVisibleRendererRecordsView = m_NativeRendererRecords.IsCreated
                    ? m_NativeRendererRecords.AsArray()
                    : default;
                m_MeshVisibleDrawBatchesView = m_NativeDrawBatchRecords.IsCreated
                    ? m_NativeDrawBatchRecords.AsArray()
                    : default;
                m_MeshVisibleRecordCountRefsView = m_MeshVisibleRecordCountRefs.AsArray();
                if (rendererRecordRefCount <= 0 && drawBatchCount <= 0)
                    return;

                EnsureMeshVisibleCountCapacity(
                    Mathf.Max(1, m_MaxMeshVisibleCountOutputCapacity));
                EnsureMeshBatchVisibleCountCapacity(
                    Mathf.Max(1, m_MaxMeshBatchVisibleCountOutputCapacity));
                NativeArray<ParticleMeshVisibleCountWork> countWorks =
                    m_MeshVisibleCountWorks.AsArray();
                NativeArray<ParticleMeshVisibleRecordCountRef> recordCountRefs =
                    m_MeshVisibleRecordCountRefs.AsArray();
                NativeArray<ParticleMeshVisibleBatchReduceWork> reduceWorks =
                    m_MeshVisibleBatchReduceWorks.AsArray();
                var collectJob = new ParticleMeshVisibleCollectJob
                {
                    RecordRefs = m_MeshVisibleRendererRecordRefsView,
                    RendererRecords = m_MeshVisibleRendererRecordsView,
                    DrawBatches = m_MeshVisibleDrawBatchesView,
                    CountWorks = countWorks,
                    RecordCountRefs = recordCountRefs,
                    ReduceWorks = reduceWorks,
                    Result = m_MeshVisibleCollectResult,
                };
                var countJob = new ParticleMeshVisibleCountJob
                {
                    Works = countWorks,
                    MeshVisibleCounts = m_MeshVisibleCounts,
                };
                var reduceJob = new ParticleMeshVisibleBatchReduceJob
                {
                    Works = reduceWorks,
                    RecordRefs = recordCountRefs,
                    RecordCounts = m_MeshVisibleCounts,
                    BatchCounts = m_MeshBatchVisibleCounts,
                };

                if (ShouldRunMeshVisibleCountInline(rendererRecordRefCount))
                {
                    using (s_MeshVisibleCollectMarker.Auto())
                    {
                        collectJob.Run();
                    }

                    for (int workIndex = 0; workIndex < rendererRecordRefCount; workIndex++)
                        countJob.Execute(workIndex);
                    for (int workIndex = 0; workIndex < drawBatchCount; workIndex++)
                        reduceJob.Execute(workIndex);
                    ApplyMeshVisibleCollectResult(scheduledPath: false);
                    return;
                }

                using (s_MeshVisibleScheduleMarker.Auto())
                {
                    JobHandle collectHandle = collectJob.Schedule();
                    JobHandle countHandle = countJob.Schedule(
                        rendererRecordRefCount,
                        innerloopBatchCount: 1,
                        collectHandle);
                    m_PendingMeshVisibleCountHandle = reduceJob.Schedule(
                        drawBatchCount,
                        innerloopBatchCount: 1,
                        countHandle);
                    m_HasPendingMeshVisibleCount = true;
                    m_PendingMeshVisibleUsesScheduledPath = true;
                    JobHandle.ScheduleBatchedJobs();
                }
            }

            private void ApplyMeshVisibleCollectResult(bool scheduledPath)
            {
                ParticleMeshVisibleCollectResult result = m_MeshVisibleCollectResult[0];
                m_MeshVisibleCountLength = result.CountOutputLength;
                m_MeshBatchVisibleCountLength = result.BatchOutputLength;
                m_LastMeshVisibleCountWorkCount = result.ValidCountWorkCount;
                m_LastMeshVisibleBatchReduceWorkCount = result.ValidReduceWorkCount;
                m_LastMeshVisibleCountInlineWorkCount = scheduledPath
                    ? 0
                    : result.ValidCountWorkCount;
                m_LastMeshVisibleCountScheduledWorkCount = scheduledPath
                    ? result.ValidCountWorkCount
                    : 0;
            }

            private void CompletePendingMeshVisibleCountGraph()
            {
                if (!m_HasPendingMeshVisibleCount)
                    return;

                using (s_MeshVisibleCompleteMarker.Auto())
                {
                    m_PendingMeshVisibleCountHandle.Complete();
                }

                ApplyCompletedMeshVisibleCountGraph();
            }

            private void ApplyCompletedMeshVisibleCountGraph()
            {
                if (!m_HasPendingMeshVisibleCount)
                    return;

                m_PendingMeshVisibleCountHandle = default;
                m_HasPendingMeshVisibleCount = false;
                ApplyMeshVisibleCollectResult(m_PendingMeshVisibleUsesScheduledPath);
                m_PendingMeshVisibleUsesScheduledPath = false;
            }

            private JobHandle SchedulePickingAndSelectionDrawCommands(
                NativeArray<ParticlePickingDrawBuildWork> works,
                JobHandle dependency)
            {
                int workCount = works.Length;
                if (workCount <= 0)
                    return default;

                int commandCapacity = Mathf.Max(
                    workCount,
                    m_MaxPickingDrawBuildCommandCapacity);
                using (s_CullingLayoutPickingCollectMarker.Auto())
                {
                    EnsureMeshVisibleCountCapacity(1);
                    EnsureNativeListCapacity(ref m_NativePickingDrawCommandInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativePickingDrawRangeInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativeSelectionDrawCommandInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativeSelectionDrawRangeInputs, commandCapacity);
                }

                using (s_CullingLayoutPickingScheduleMarker.Auto())
                {
                    return new ParticlePickingDrawCommandBuildJob
                    {
                        Works = works,
                        MeshIds = m_CullingBatchMeshIds.AsArray(),
                        MeshVisibleCounts = m_MeshVisibleCounts,
                        PickingCommands = m_NativePickingDrawCommandInputs,
                        PickingRanges = m_NativePickingDrawRangeInputs,
                        SelectionCommands = m_NativeSelectionDrawCommandInputs,
                        SelectionRanges = m_NativeSelectionDrawRangeInputs,
                        Result = m_PickingDrawBuildResult,
                    }.Schedule(dependency);
                }
            }

            private JobHandle ScheduleBatchDrawCommands(
                NativeArray<ParticleBatchDrawBuildWork> works,
                JobHandle dependency)
            {
                int workCount = works.Length;
                if (workCount <= 0)
                    return default;

                int commandCapacity = Mathf.Max(
                    workCount,
                    m_MaxBatchDrawBuildCommandCapacity);
                using (s_CullingLayoutBatchDrawCollectMarker.Auto())
                {
                    EnsureMeshBatchVisibleCountCapacity(1);
                    EnsureNativeListCapacity(ref m_NativeDrawCommandInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativeDrawRangeInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativeLightDrawCommandInputs, commandCapacity);
                    EnsureNativeListCapacity(ref m_NativeLightDrawRangeInputs, commandCapacity);
                }

                using (s_CullingLayoutBatchDrawScheduleMarker.Auto())
                {
                    return new ParticleBatchDrawCommandBuildJob
                    {
                        Works = works,
                        MeshIds = m_CullingBatchMeshIds.AsArray(),
                        MeshVisibleCounts = m_MeshBatchVisibleCounts,
                        CameraCommands = m_NativeDrawCommandInputs,
                        CameraRanges = m_NativeDrawRangeInputs,
                        LightCommands = m_NativeLightDrawCommandInputs,
                        LightRanges = m_NativeLightDrawRangeInputs,
                        Result = m_BatchDrawBuildResult,
                    }.Schedule(dependency);
                }
            }

            private void ApplyPickingAndSelectionDrawBuildResult()
            {
                ParticlePickingDrawBuildResult result = m_PickingDrawBuildResult[0];
                m_NativePickingVisibleInstanceCapacity = result.PickingVisibleInstanceCapacity;
                m_NativeSelectionVisibleInstanceCapacity = result.SelectionVisibleInstanceCapacity;
                m_NativePickingDrawCommandLayerMask = result.PickingLayerMask;
                m_NativeSelectionDrawCommandLayerMask = result.SelectionLayerMask;
                m_NativePickingDrawCommandSceneCullingMask = result.PickingSceneCullingMask;
                m_NativeSelectionDrawCommandSceneCullingMask = result.SelectionSceneCullingMask;
                m_AnySelectedRecord = result.AnySelectedRecord != 0;
                m_LastCullingRecordVisibleCacheEntryCount = m_NativePickingDrawCommandInputs.Length;
            }

            private void ApplyBatchDrawBuildResult()
            {
                ParticleBatchDrawBuildResult result = m_BatchDrawBuildResult[0];
                m_NativeVisibleInstanceCapacity = result.CameraVisibleInstanceCapacity;
                m_NativeSortingPositionCapacity = result.CameraSortingPositionCapacity;
                m_NativeLightVisibleInstanceCapacity = result.LightVisibleInstanceCapacity;
                m_NativeDrawCommandLayerMask = result.CameraLayerMask;
                m_NativeLightDrawCommandLayerMask = result.LightLayerMask;
                m_NativeDrawCommandSceneCullingMask = result.CameraSceneCullingMask;
                m_NativeLightDrawCommandSceneCullingMask = result.LightSceneCullingMask;
                m_LastCullingBatchVisibleCacheEntryCount = result.CameraCommandCount;
                m_AnyShadowCastingBatch = result.AnyShadowCastingBatch != 0;
            }

            private void ApplyCullingLayoutCollectResult()
            {
                ParticleCullingLayoutCollectResult result = m_CullingLayoutCollectResult[0];
                m_NativeCullingRecordLength = result.CullingRecordCount;
                m_LastInvalidRendererRecordRefCount = result.InvalidRecordRefCount;
                m_LastCullingSingleMeshCacheRecordCount = result.SingleMeshRecordCount;
                m_LastCullingMeshFallbackRecordCount = result.MultiMeshFallbackRecordCount;
                m_LastVisibleInstanceCapacityCacheEntryCount =
                    result.VisibleInstanceCapacityCacheEntryCount;
                m_LastCullingRecordBuildWorkCount = result.ValidCullingWorkCount;
                m_LastCullingCollectValidRecordCount = result.ValidCullingWorkCount;
                m_LastPickingDrawBuildWorkCount = result.ValidPickingWorkCount;
                m_PickingDrawBuildCommandCapacity = result.PickingDrawCommandCapacity;
                m_LastBatchDrawBuildWorkCount = result.ValidBatchWorkCount;
                m_BatchDrawBuildCommandCapacity = result.BatchDrawCommandCapacity;
            }

            private static void EnsureNativeListCapacity<T>(ref NativeList<T> list, int capacity)
                where T : unmanaged
            {
                if (list.Capacity < capacity)
                    list.Capacity = capacity;
            }

            private void BuildDrawCommandsFromCullingRecords(
                JobHandle collectHandle,
                NativeArray<ParticlePickingDrawBuildWork> pickingWorks,
                NativeArray<ParticleBatchDrawBuildWork> batchWorks)
            {
                bool hasPickingWork = pickingWorks.Length > 0;
                bool hasBatchWork = batchWorks.Length > 0;
                bool hasCollectWork = hasPickingWork || hasBatchWork;
                if (!hasCollectWork && !hasPickingWork && !hasBatchWork)
                    return;

                JobHandle combinedHandle = collectHandle;
                if (hasPickingWork)
                {
                    JobHandle pickingHandle =
                        SchedulePickingAndSelectionDrawCommands(pickingWorks, collectHandle);
                    combinedHandle = JobHandle.CombineDependencies(combinedHandle, pickingHandle);
                }

                if (hasBatchWork)
                {
                    JobHandle batchHandle = ScheduleBatchDrawCommands(batchWorks, collectHandle);
                    combinedHandle = JobHandle.CombineDependencies(combinedHandle, batchHandle);
                }

                JobHandle.ScheduleBatchedJobs();
                using (s_CullingLayoutDrawBuildCompleteMarker.Auto())
                {
                    combinedHandle.Complete();
                }

                ApplyCompletedMeshVisibleCountGraph();
                ApplyCullingLayoutCollectResult();
                if (hasPickingWork)
                    ApplyPickingAndSelectionDrawBuildResult();
                if (hasBatchWork)
                    ApplyBatchDrawBuildResult();
            }

            private void RebuildBatches()
            {
                using (s_RebuildBatchesMarker.Auto())
                {
                    DrainCullingResults();
                    CompletePendingMeshVisibleCountGraph();
                    EnsureNativeCullingLayout();
                    m_RendererRecordRefs.Clear();
                    m_TotalBufferByteSize = 0;
                    m_LastGpuBufferInfoCount = 0;
                    m_LastRecordCopyDescriptorCount = 0;
                    m_LastSharedValueBufferInfoCount = 0;
                    m_LastPerSharpValueBufferInfoCount = 0;
                    m_LastReusedDrawBatchCount = 0;
                    m_LastCreatedDrawBatchCount = 0;
                    int cullingPageBoundsOffset = 0;

                    bool groupMembershipChanged = RebuildRendererLineGroupsFromEcsQuery();
                    if (groupMembershipChanged)
                    {
                        ClearDrawBatches();
                        BuildDrawBatchesFromEcsGroups();
                        m_DrawBatches.Sort(s_DrawBatchSortComparer);
                    }

                    for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                    {
                        ParticleDrawBatch batch = m_DrawBatches[batchIndex];
                        batch.BatchIndex = batchIndex;
                        batch.Capacity = 0;
                        batch.SpanCapacity = 0;
                        batch.SceneCullingMask = 0UL;
                        batch.RequiresSortingPositions = false;
                        int batchRecordCount = batch.RecordRefCount;
                        for (int recordIndex = 0; recordIndex < batchRecordCount; recordIndex++)
                        {
                            ParticleRendererRecordRef recordRef =
                                m_EcsBatchRecordRefs[batch.RecordRefStart + recordIndex];
                            if (!TryGetRecord(
                                    recordRef.RecordSlot,
                                    recordRef.RecordVersion,
                                    out ParticleRenderRecord record)
                                || !TryGetNativeRendererRecord(
                                    recordRef.RecordSlot,
                                    recordRef.RecordVersion,
                                    out ParticleRendererDynamicRecord dynamicRecord))
                            {
                                m_LastInvalidRendererRecordRefCount++;
                                continue;
                            }

                            record.State?.InvalidateRendererBoundsCache();
                            if (record.State != null)
                                record.State.RefreshRendererDynamicBoundsData(ref dynamicRecord);
                            m_NativeRendererRecords[record.RecordSlot] = dynamicRecord;

                            int recordCapacity = Mathf.Max(1, dynamicRecord.RenderCapacity);
                            VividParticleRenderMode renderMode =
                                (VividParticleRenderMode)dynamicRecord.RenderMode;
                            record.Batch = batch;
                            record.BatchBaseIndex = batch.Capacity;
                            record.SharpIndex = recordIndex;
                            record.SpanBaseIndex = batch.SpanCapacity;
                            record.SpanCapacity = GetVisibleInstanceCount(renderMode, recordCapacity);
                            record.CullingPageBoundsOffset = cullingPageBoundsOffset;
                            record.CullingPageBoundsCapacity = Mathf.Max(
                                1,
                                GetCullingRecordCount(recordCapacity));
                            cullingPageBoundsOffset += record.CullingPageBoundsCapacity;
                            SyncNativeRendererLayout(record);
                            m_RendererRecordRefs.Add(new ParticleRendererRecordRef
                            {
                                RecordSlot = record.RecordSlot,
                                RecordVersion = record.RecordVersion,
                                BatchIndex = batchIndex,
                            });
                            batch.RequiresSortingPositions |= RequiresSortingPositions(
                                (VividParticleSortMode)dynamicRecord.SortMode);
                            batch.SceneCullingMask |= dynamicRecord.SceneCullingMask;
                            batch.Capacity += recordCapacity;
                            batch.SpanCapacity += Mathf.Max(1, record.SpanCapacity);
                        }

                        batch.SceneCullingMask = ResolveParticleSceneCullingMask(batch.SceneCullingMask);
                        batch.Capacity = Mathf.Max(1, batch.Capacity);
                        NormalizeBatchMeshes(batch);
                        batch.SharpCapacity = Mathf.Max(1, batchRecordCount);
                        batch.SpanCapacity = Mathf.Max(1, batch.SpanCapacity);
                        batch.DataOffset = AlignTo16(m_TotalBufferByteSize);
                        EnsureBatchBufferInfoList(ref batch.GpuBufferInfos, batch.GpuLayout.Count);
                        batch.GpuLayout.FillBufferInfos(
                            batch.GpuBufferInfos,
                            batch.Capacity,
                            batch.SharpCapacity,
                            batch.SpanCapacity);
                        BuildBatchGpuDataDerivedArrays(batch);
                        m_TotalBufferByteSize = batch.DataOffset + batch.GpuLayout.CalculateByteSize(
                            batch.Capacity,
                            batch.SharpCapacity,
                            batch.SpanCapacity);
                    }

                    m_CullingPageBoundsCount = cullingPageBoundsOffset;
                    EnsureBoundsResultCapacity(
                        Mathf.Max(1, m_CullingPageBoundsCount),
                        Mathf.Max(1, m_RecordSlots.Count));
                    m_BoundsRequiredPageCapacity = m_CullingPageBoundsCount;

                    bool bufferChanged = m_GPUBuffer.EnsureCapacity(Mathf.Max(ZeroBlockByteSize, m_TotalBufferByteSize));
                    RebuildBatchRendererGroup();
                    RebuildCullingBatchMeshIds();
                    RebuildNativeDrawBatchRecords();
                    m_ForceFullUpload = true;
                    m_LayoutDirty = false;
                }
            }

            private ParticleDrawBatch AcquireDrawBatch(
                ParticleRendererBatchSeed seed,
                VividParticleRendererSharedKey groupKey)
            {
                ParticleDrawBatch batch;
                if (m_DrawBatchPool.Count > 0)
                {
                    batch = m_DrawBatchPool.Pop();
                    m_LastReusedDrawBatchCount++;
                }
                else
                {
                    batch = new ParticleDrawBatch();
                    m_LastCreatedDrawBatchCount++;
                }

                batch.Key = groupKey;
                batch.Material = seed.Material;
                batch.Mesh = seed.Mesh;
                batch.Meshes = seed.Meshes ?? Array.Empty<Mesh>();
                batch.MeshCount = seed.MeshCount;
                batch.ShadowCastingMode = seed.ShadowCastingMode;
                batch.MotionMode = seed.MotionMode;
                batch.ReceiveShadows = seed.ReceiveShadows;
                batch.StaticShadowCaster = seed.StaticShadowCaster;
                batch.SortingPriority = seed.SortingPriority;
                batch.BatchLayer = seed.BatchLayer;
                batch.SceneCullingMask = 0UL;
                batch.UsesPageBillboard = UsesPageBillboardRenderMode(seed.RenderMode);
                batch.RequiresSortingPositions = false;
                batch.GpuLayout = seed.GpuLayout;
                batch.BatchId = BatchID.Null;
                batch.MeshId = BatchMeshID.Null;
                batch.MaterialId = default;
                batch.CullingMeshIdOffset = -1;
                batch.BatchIndex = -1;
                batch.Capacity = 0;
                batch.SharpCapacity = 0;
                batch.SpanCapacity = 0;
                batch.DataOffset = 0;
                return batch;
            }

            private static void NormalizeBatchMeshes(ParticleDrawBatch batch)
            {
                if (batch == null)
                    return;

                if (batch.UsesPageBillboard)
                {
                    batch.MeshCount = SetSingleBatchMesh(batch, batch.Mesh);
                    return;
                }

                Mesh[] meshes = batch.Meshes;
                int count = Mathf.Clamp(batch.MeshCount, 0, meshes?.Length ?? 0);
                if (count <= 0)
                {
                    batch.MeshCount = SetSingleBatchMesh(batch, batch.Mesh);
                    return;
                }

                int write = 0;
                for (int index = 0; index < count; index++)
                {
                    Mesh mesh = meshes[index];
                    if (mesh == null)
                        continue;

                    meshes[write++] = mesh;
                }

                if (write == count)
                {
                    batch.MeshCount = write;
                    return;
                }

                if (write <= 0)
                {
                    batch.MeshCount = SetSingleBatchMesh(batch, batch.Mesh);
                    return;
                }

                Array.Clear(meshes, write, count - write);
                batch.MeshCount = write;
            }

            private static int SetSingleBatchMesh(ParticleDrawBatch batch, Mesh mesh)
            {
                if (batch == null || mesh == null)
                {
                    if (batch != null)
                        batch.MeshCount = 0;

                    return 0;
                }

                if (batch.Meshes == null || batch.Meshes.Length == 0)
                    batch.Meshes = new Mesh[1];

                batch.Meshes[0] = mesh;
                return 1;
            }

            private void RebuildBatchRendererGroup()
            {
                m_BRG?.Dispose();
                m_BRG = null;

                if (m_DrawBatches.Count == 0 || m_GPUBuffer.renderBuffer == null)
                    return;

                m_BRG = new BatchRendererGroup(new BatchRendererGroupCreateInfo
                {
                    cullingCallback = OnPerformCulling,
                    userContext = IntPtr.Zero,
                });
#if UNITY_EDITOR
                m_BRG.SetEnabledViewTypes(s_EnabledEditorViewTypes);

                Material pickingMaterial = GetOrCreatePickingMaterial();
                if (pickingMaterial != null)
                    m_BRG.SetPickingMaterial(pickingMaterial);
#endif

                for (int index = 0; index < m_DrawBatches.Count; index++)
                {
                    ParticleDrawBatch batch = m_DrawBatches[index];
                    int meshCount = Mathf.Clamp(batch.MeshCount, 0, batch.Meshes?.Length ?? 0);
                    if (meshCount <= 0)
                        continue;

                    if (batch.MeshIds == null || batch.MeshIds.Length < meshCount)
                        batch.MeshIds = new BatchMeshID[meshCount];

                    for (int meshIndex = 0; meshIndex < meshCount; meshIndex++)
                        batch.MeshIds[meshIndex] = m_BRG.RegisterMesh(batch.Meshes[meshIndex]);

                    batch.MeshId = batch.MeshIds[0];
                    batch.MaterialId = m_BRG.RegisterMaterial(batch.Material);

                    if (!batch.GpuBufferInfos.IsCreated || batch.GpuBufferInfos.Length <= 0)
                        continue;

                    EnsureMetadataScratch(batch.GpuBufferInfos.Length);
                    m_MetadataScratch.Clear();
                    for (int metadataIndex = 0; metadataIndex < batch.GpuBufferInfos.Length; metadataIndex++)
                    {
                        VividParticleGpuBufferDataInfo bufferInfo = batch.GpuBufferInfos[metadataIndex];
                        m_MetadataScratch.Add(CreateMetadataValue(
                            bufferInfo.DataInfo,
                            batch.DataOffset + bufferInfo.ByteOffset));
                    }

                    batch.BatchId = m_BRG.AddBatch(
                        m_MetadataScratch.AsArray(),
                        m_GPUBuffer.renderBuffer.bufferHandle,
                        0u,
                        ResolveBufferWindowSize());

                    int batchRecordCount = batch.RecordRefCount;
                    for (int recordIndex = 0; recordIndex < batchRecordCount; recordIndex++)
                    {
                        ParticleRendererRecordRef recordRef =
                            m_EcsBatchRecordRefs[batch.RecordRefStart + recordIndex];
                        if (TryGetRecord(
                                recordRef.RecordSlot,
                                recordRef.RecordVersion,
                                out ParticleRenderRecord record))
                        {
                            record.State?.ResetRendererCullingStats();
                        }
                    }
                }
            }

            private void EnsureMetadataScratch(int capacity)
            {
                int clampedCapacity = Mathf.Max(1, capacity);
                if (!m_MetadataScratch.IsCreated)
                {
                    m_MetadataScratch = new NativeList<MetadataValue>(clampedCapacity, Allocator.Persistent);
                    return;
                }

                if (m_MetadataScratch.Capacity < clampedCapacity)
                    m_MetadataScratch.Capacity = clampedCapacity;
            }

            private static MetadataValue CreateMetadataValue(
                VividParticleGpuDataInfo dataInfo,
                int byteAddress)
            {
                int shaderPropertyId = GetGpuDataShaderPropertyId(dataInfo.DataId);
                return dataInfo.UsesInstanceMetadata
                    ? CreatePerInstanceMetadata(shaderPropertyId, byteAddress)
                    : CreateSharedMetadata(shaderPropertyId, byteAddress);
            }

#if UNITY_EDITOR
            private Material GetOrCreatePickingMaterial()
            {
                if (m_PickingMaterial != null)
                    return m_PickingMaterial;

                Shader shader = Shader.Find(PickingShaderName);
                if (shader == null)
                    return null;

                m_PickingMaterial = new Material(shader)
                {
                    name = "Vivid Particle BRG Picking Material",
                    hideFlags = HideFlags.HideAndDontSave,
                };
                ParticleSystemState.ConfigureDefaultParticleMaterial(m_PickingMaterial);
                return m_PickingMaterial;
            }
#endif

            private static int GetGpuDataShaderPropertyId(VividParticleGpuDataId dataId)
            {
                return dataId switch
                {
                    VividParticleGpuDataId.SharedData => s_SharedDataId,
                    VividParticleGpuDataId.SpanSharedData => s_SpanSharedDataId,
                    VividParticleGpuDataId.PositionSize => s_PositionSizeId,
                    VividParticleGpuDataId.BaseColor => s_BaseColorId,
                    VividParticleGpuDataId.Rotation => s_RotationId,
                    VividParticleGpuDataId.VelocityStretch => s_VelocityStretchId,
                    VividParticleGpuDataId.Scale => s_ScaleId,
                    VividParticleGpuDataId.UV => s_UVId,
                    VividParticleGpuDataId.CustomData1 => s_CustomData1Id,
                    VividParticleGpuDataId.CustomData2 => s_CustomData2Id,
                    VividParticleGpuDataId.MeshIndex => s_MeshIndexId,
                    _ => 0,
                };
            }

            private void BuildBatchGpuDataDerivedArrays(ParticleDrawBatch batch)
            {
                batch.HasSharedDataBufferInfo = false;
                batch.HasSpanSharedDataBufferInfo = false;
                batch.SharedDataBufferInfo = default;
                batch.SpanSharedDataBufferInfo = default;
                batch.UploadColumnLayout = CreateEmptyUploadColumnLayout();

                if (batch.GpuBufferInfos.IsCreated && batch.GpuBufferInfos.Length > 0)
                {
                    int bufferInfoCount = batch.GpuBufferInfos.Length;
                    for (int dataIndex = 0; dataIndex < bufferInfoCount; dataIndex++)
                    {
                        VividParticleGpuBufferDataInfo bufferInfo = batch.GpuBufferInfos[dataIndex];
                        VividParticleGpuDataInfo dataInfo = bufferInfo.DataInfo;
                        if (dataInfo.CreatesRecordCopyDescriptor)
                            m_LastRecordCopyDescriptorCount++;

                        switch (dataInfo.Role)
                        {
                            case VividParticleGpuDataRole.SharedValue:
                                m_LastSharedValueBufferInfoCount++;
                                break;

                            case VividParticleGpuDataRole.PerSharpValue:
                                m_LastPerSharpValueBufferInfoCount++;
                                break;

                            case VividParticleGpuDataRole.SharedDataBlock:
                                batch.SharedDataBufferInfo = bufferInfo;
                                batch.HasSharedDataBufferInfo = true;
                                break;

                            case VividParticleGpuDataRole.SpanSharedDataBlock:
                                batch.SpanSharedDataBufferInfo = bufferInfo;
                                batch.HasSpanSharedDataBufferInfo = true;
                                break;
                        }

                        if (dataInfo.IsPerInstance && dataInfo.HasUploadSegment)
                        {
                            SetUploadColumnLayoutOffset(
                                ref batch.UploadColumnLayout,
                                dataInfo,
                                bufferInfo.ByteOffset);
                        }
                    }
                }
                m_LastGpuBufferInfoCount += batch.GpuBufferInfos.IsCreated
                    ? batch.GpuBufferInfos.Length
                    : 0;
            }

            private static void EnsureBatchBufferInfoList(
                ref NativeList<VividParticleGpuBufferDataInfo> bufferInfos,
                int capacity)
            {
                int clampedCapacity = Mathf.Max(1, capacity);
                if (!bufferInfos.IsCreated)
                {
                    bufferInfos = new NativeList<VividParticleGpuBufferDataInfo>(
                        clampedCapacity,
                        Allocator.Persistent);
                    return;
                }

                if (bufferInfos.Capacity < clampedCapacity)
                    bufferInfos.Capacity = clampedCapacity;
            }

            private void ScheduleRenderUploadGraph()
            {
                using (s_UploadMarker.Auto())
                {
                    if (m_HasPendingUpload)
                        CompletePendingUpload();
                    else
                        CompletePendingUploadPageBuild();

                    EnsureNativeUploadQueues();
                    bool forceFullUpload = m_ForceFullUpload;
                    bool hasUpload = false;
                    using (s_UploadCollectDirtyMarker.Auto())
                    {
                        m_UploadRecordWorks.Clear();
                        m_UploadBatchWorks.Clear();
                        m_UploadPageRangeWorks.Clear();
                        m_TransformUploadPageWorks.Clear();
                        m_ColorUploadPageWorks.Clear();
                        m_VelocityStretchUploadPageWorks.Clear();
                        m_UVUploadPageWorks.Clear();
                        m_CustomDataUploadPageWorks.Clear();
                        m_MeshIndexUploadPageWorks.Clear();
                        m_SharedDataWorks.Clear();
                        m_GroupedSharedDataWorks.Clear();
                        m_SharedDataWorkGroups.Clear();
                        m_LastSharedDataWorkGroupCount = 0;
                        m_UploadCopyWorks.Clear();
                        m_UploadCopyCollectWorks.Clear();
                        m_UploadCopyCollectResults.Clear();
                        m_UploadCopyCompactResult[0] = default;
                        m_UploadCopyCollectOutputCapacity = 0;
                        m_UploadCopyWorksAreSorted = true;
                        m_PendingRenderJobFlags = 0u;
                        m_LastDirtyUploadQueueCount = forceFullUpload || !m_DirtyUploadRecords.IsCreated
                            ? 0
                            : m_DirtyUploadRecords.Length;
                        m_LastDirtyUploadBatchQueueCount = forceFullUpload || !m_DirtyUploadBatchIndices.IsCreated
                            ? 0
                            : m_DirtyUploadBatchIndices.Length;
                        m_LastInvalidDirtyUploadQueueCount = 0;
                        m_LastInvalidDirtyUploadBatchQueueCount = 0;
                        m_LastUploadRecordWorkCount = 0;
                        m_LastUploadBatchWorkCount = 0;
                        m_LastNativeUploadRequestCollectCount = 0;
                        m_LastManagedUploadRequestCollectCount = 0;
                        m_LastUploadPageWorkCount = 0;
                        ResetCachedUploadPageWorkCounts();
                        m_LastMergedUploadCopyWorkCount = 0;
                        m_LastUploadCopySortCount = 0;
                        m_LastUploadCopyCollectWorkCount = 0;
                        m_LastUploadCopyWorkCount = 0;
                        m_LastUploadColumnMask = 0;
                        m_LastUploadDataBits = 0u;
                        m_LastSharedDataFloat4Mask = 0u;
                        m_LastRenderJobModuleFlags = 0u;
                        m_LastRenderPageJobModuleCount = 0;
                        m_LastRenderKernelFlags = 0u;
                        m_LastAnimatedTransformPageWorkCount = 0;
                        m_LastAnimatedColorPageWorkCount = 0;
                        m_LastAnimatedVelocityPageWorkCount = 0;

                        if (forceFullUpload)
                        {
                            int nativeBatchCount = m_NativeDrawBatchRecords.IsCreated
                                ? m_NativeDrawBatchRecords.Length
                                : 0;
                            for (int batchIndex = 0; batchIndex < nativeBatchCount; batchIndex++)
                            {
                                if (!TryGetNativeDrawBatchRecord(
                                        batchIndex,
                                        out ParticleNativeDrawBatchRecord nativeBatch))
                                {
                                    continue;
                                }

                                nativeBatch.UploadDirtyQueued = 0;
                                m_NativeDrawBatchRecords[batchIndex] = nativeBatch;
                                hasUpload |= TryAddUploadBatchWork(
                                    batchIndex,
                                    nativeBatch,
                                    forceFullUpload: true);
                            }

                            if (m_DirtyUploadBatchIndices.IsCreated)
                                m_DirtyUploadBatchIndices.Clear();

                            for (int recordSlot = 0; recordSlot < m_RecordSlots.Count; recordSlot++)
                            {
                                ParticleRenderRecord record = m_RecordSlots[recordSlot];
                                bool added = TryAddUploadRecordWork(record, forceFullUpload);
                                hasUpload |= added;
                                if (added)
                                    m_LastManagedUploadRequestCollectCount++;
                            }

                            if (m_DirtyUploadRecords.IsCreated)
                                m_DirtyUploadRecords.Clear();
                        }
                        else if (m_DirtyUploadRecords.IsCreated)
                        {
                            hasUpload |= DrainDirtyUploadBatchQueue();
                            for (int dirtyIndex = 0; dirtyIndex < m_DirtyUploadRecords.Length; dirtyIndex++)
                            {
                                ParticleUploadRecordRef dirtyRecord = m_DirtyUploadRecords[dirtyIndex];
                                if (!TryAddNativeUploadRecordWork(dirtyRecord))
                                {
                                    m_LastInvalidDirtyUploadQueueCount++;
                                    continue;
                                }

                                m_LastNativeUploadRequestCollectCount++;
                                hasUpload = true;
                            }

                            m_DirtyUploadRecords.Clear();
                        }

                        m_LastUploadRecordWorkCount = m_UploadRecordWorks.Length;
                        m_LastUploadBatchWorkCount = m_UploadBatchWorks.Length;
                    }

                    if (!hasUpload)
                    {
                        m_GPUBuffer.ResetLastUploadStats();
                        m_LastUploadRecordWorkCount = 0;
                        m_LastUploadBatchWorkCount = 0;
                        m_LastUploadPageWorkCount = 0;
                        ResetCachedUploadPageWorkCounts();
                        m_LastUploadColumnMask = 0;
                        m_LastUploadDataBits = 0u;
                        m_LastUploadCopySortCount = 0;
                        m_LastUploadCopyCollectWorkCount = 0;
                        m_LastUploadCopyWorkCount = 0;
                        m_UploadCopyWorksAreSorted = true;
                        m_ForceFullUpload = false;
                        return;
                    }

                    byte* bufferBase;
                    using (s_UploadLockBufferMarker.Auto())
                    {
                        bufferBase = m_GPUBuffer.BeginWrite();
                    }

                    if (bufferBase == null)
                    {
                        return;
                    }

                    try
                    {
                        using (s_UploadBuildWorksMarker.Auto())
                        {
                            NativeArray<VividParticleGpuBufferDataInfo> nativeSharedValueBufferInfos =
                                m_NativeSharedValueBufferInfos.IsCreated
                                    ? m_NativeSharedValueBufferInfos.AsArray()
                                    : default;
                            NativeArray<VividParticleGpuBufferDataInfo> nativePerSharpValueBufferInfos =
                                m_NativePerSharpValueBufferInfos.IsCreated
                                    ? m_NativePerSharpValueBufferInfos.AsArray()
                                    : default;
                                AddBatchSharedDataWorks(
                                    bufferBase,
                                    forceFullUpload,
                                    nativeSharedValueBufferInfos);

                            for (int workIndex = 0; workIndex < m_UploadRecordWorks.Length; workIndex++)
                            {
                                ParticleUploadRecordWork work = m_UploadRecordWorks[workIndex];
                                if (!TryGetNativeDrawBatchRecord(
                                        work.BatchIndex,
                                        out ParticleNativeDrawBatchRecord nativeBatch)
                                    || !TryGetNativeRendererRecord(
                                        work.RecordSlot,
                                        work.RecordVersion,
                                        out ParticleRendererDynamicRecord dynamicRecord))
                                {
                                    continue;
                                }

                                int count = Mathf.Clamp(
                                    work.Count,
                                    0,
                                    Mathf.Max(0, dynamicRecord.ActiveCount - work.StartIndex));
                                bool hasInstanceRange = work.HasInstanceRange != 0 && count > 0;
                                bool hasSpanData = work.HasSpanData != 0;
                                int columnMask = work.ColumnMask;
                                uint sharedDataBits = work.SharedDataBits;
                                int sharedStartIndex = hasInstanceRange ? work.StartIndex : 0;
                                int sharedCount = hasInstanceRange
                                    ? count
                                    : dynamicRecord.ActiveCount;
                                if (!hasInstanceRange && sharedCount <= 0)
                                    continue;

                                if (hasInstanceRange && work.HasUploadSource != 0)
                                {
                                    ParticleRenderUploadSource source = work.UploadSource;
                                    source.ActiveCount = dynamicRecord.ActiveCount;
                                    source.BatchBaseIndex = dynamicRecord.BatchBaseIndex;
                                    source.BatchDataOffset = nativeBatch.DataOffset;
                                    source.BufferBase = bufferBase;
                                    AddUploadPageWorks(
                                        nativeBatch.UploadColumnLayout,
                                        source,
                                        work.StartIndex,
                                        count,
                                        columnMask);
                                }

                                AddRecordSharedDataWorks(
                                    bufferBase,
                                    work.BatchIndex,
                                    nativeBatch,
                                    dynamicRecord,
                                    sharedStartIndex,
                                    sharedCount,
                                    sharedDataBits,
                                    work.SharedDataFloat4Mask,
                                    hasSpanData,
                                    nativePerSharpValueBufferInfos);
                                AddGpuDataCopyCollectWork(
                                    nativeBatch,
                                    work,
                                    dynamicRecord,
                                    count,
                                    sharedStartIndex,
                                    sharedCount);
                            }
                        }

                        CaptureCachedUploadPageWorkCounts();
                        ClearPendingUploadViews();
                        JobHandle copyCollectHandle = ScheduleUploadCopyCollectGraph();
                        m_PendingUploadHandle = copyCollectHandle;
                        JobHandle renderUploadGraphHandle = default;
                        bool hasPageUploadWorks = HasUploadPageWorks();
                        bool hasPageRangeWorks = m_UploadPageRangeWorks.Length > 0;
                        if (hasPageUploadWorks || m_SharedDataWorks.Length > 0)
                        {
                            using (s_UploadCopyWorkArraysMarker.Auto())
                            {
                                CapturePendingUploadPageWorks();

                                if (m_SharedDataWorks.Length > 0)
                                    PreparePendingSharedDataWorkGroups();
                            }

                            var pageJobWorkSet = new ParticleRenderPageJobWorkSet(
                                m_PendingTransformUploadPageWorks,
                                m_PendingColorUploadPageWorks,
                                m_PendingVelocityStretchUploadPageWorks,
                                m_PendingUVUploadPageWorks,
                                m_PendingCustomDataUploadPageWorks,
                                m_PendingMeshIndexUploadPageWorks);
                            JobHandle pageWorkBuildHandle = JobHandle.CombineDependencies(
                                ScheduleUploadPageWorkBuild(),
                                ScheduleSharedDataWorkGroupBuild());
                            m_PendingUploadPageBuildHandle = pageWorkBuildHandle;
                            m_HasPendingUploadPageBuild = hasPageRangeWorks
                                || m_HasPendingSharedDataWorkGroupBuild;
                            JobHandle renderDependency = m_HasParticleDataDependency
                                ? JobHandle.CombineDependencies(
                                    pageWorkBuildHandle,
                                    m_ParticleDataDependency)
                                : pageWorkBuildHandle;
                            using (s_UploadScheduleJobsMarker.Auto())
                            {
                                m_LastRenderJobModuleFlags = m_PendingRenderJobFlags;
                                m_LastRenderPageJobModuleCount = CountRenderPageJobModules(m_PendingRenderJobFlags);
                                JobHandle renderUploadHandle = VividParticleRenderJobPipeline.Schedule(
                                    pageJobWorkSet,
                                    m_PendingSharedDataWorks,
                                    m_PendingSharedDataPages,
                                    m_PendingSharedDataWorkGroups,
                                    m_PendingRenderJobFlags,
                                    renderDependency);
                                renderUploadGraphHandle = JobHandle.CombineDependencies(
                                    pageWorkBuildHandle,
                                    renderUploadHandle);
                            }
                        }
                        else
                        {
                            m_LastRenderJobModuleFlags = 0u;
                            m_LastRenderPageJobModuleCount = 0;
                        }

                        m_PendingUploadHandle = JobHandle.CombineDependencies(
                            copyCollectHandle,
                            renderUploadGraphHandle);
                        JobHandle.ScheduleBatchedJobs();
                        m_HasPendingUpload = true;
                    }
                    catch
                    {
                        m_PendingUploadHandle.Complete();
                        CompletePendingUploadPageBuild();
                        ClearPendingUploadViews();
                        m_PendingUploadHandle = default;
                        m_HasPendingUpload = false;
                        m_HasPendingUploadCopyCollect = false;
                        m_GPUBuffer.EndWrite();
                        m_ForceFullUpload = true;
                        throw;
                    }
                }
            }

            public void CompletePendingUpload()
            {
                CompletePendingBoundsUpdates();

                if (!m_HasPendingUpload)
                {
                    CompletePendingUploadPageBuild();
                    return;
                }

                using (s_CompleteUploadMarker.Auto())
                {
                    m_PendingUploadHandle.Complete();
                    m_PendingUploadHandle = default;
                    CompletePendingUploadPageBuild();
                    ClearPendingUploadViews();

                    ApplyUploadCopyCollectResult();
                    AddPendingUploadCopyOperations();
                    m_GPUBuffer.EndWrite();

                    for (int workIndex = 0; workIndex < m_UploadRecordWorks.Length; workIndex++)
                    {
                        ParticleUploadRecordWork work = m_UploadRecordWorks[workIndex];
                        if (TryGetRecord(
                                work.RecordSlot,
                                work.RecordVersion,
                                out ParticleRenderRecord record)
                            && TryGetNativeRendererRecord(
                                work.RecordSlot,
                                work.RecordVersion,
                                out ParticleRendererDynamicRecord dynamicRecord)
                            && TryGetNativePendingUploadState(
                                work.RecordSlot,
                                work.RecordVersion,
                                out ParticlePendingUploadState pendingState))
                        {
                            bool requestCompleted = work.UploadRevision < 0
                                || pendingState.Revision == work.UploadRevision;
                            if (requestCompleted)
                            {
                                record.State.ClearUploadDirty();
                                pendingState.IsQueued = 0;
                                pendingState.Request = default;
                                m_NativePendingUploadStates[work.RecordSlot] = pendingState;
                            }

                            record.State.SetRendererUploadStats(
                                true,
                                dynamicRecord.ActiveCount,
                                dynamicRecord.LastUploadOperationCount,
                                dynamicRecord.LastUploadByteCount,
                                m_GPUBuffer.bufferIndex);
                        }
                    }

                    m_ForceFullUpload = false;
                    m_HasPendingUpload = false;
                }
            }

            private void CompletePendingUploadPageBuild()
            {
                if (!m_HasPendingUploadPageBuild)
                    return;

                m_PendingUploadPageBuildHandle.Complete();
                m_PendingUploadPageBuildHandle = default;
                m_HasPendingUploadPageBuild = false;
                if (m_HasPendingSharedDataWorkGroupBuild)
                {
                    m_LastSharedDataWorkGroupCount = m_SharedDataWorkGroupBuildResult.IsCreated
                        ? m_SharedDataWorkGroupBuildResult[0]
                        : 0;
                    m_HasPendingSharedDataWorkGroupBuild = false;
                }
            }

            private void ClearPendingUploadViews()
            {
                m_PendingTransformUploadPageWorks = default;
                m_PendingColorUploadPageWorks = default;
                m_PendingVelocityStretchUploadPageWorks = default;
                m_PendingUVUploadPageWorks = default;
                m_PendingCustomDataUploadPageWorks = default;
                m_PendingMeshIndexUploadPageWorks = default;
                m_PendingSharedDataWorks = default;
                m_PendingSharedDataPages = default;
                m_PendingSharedDataWorkGroups = default;
            }

            private void PreparePendingSharedDataWorkGroups()
            {
                int workCount = m_SharedDataWorks.IsCreated ? m_SharedDataWorks.Length : 0;
                int batchCount = m_NativeDrawBatchRecords.IsCreated
                    ? m_NativeDrawBatchRecords.Length
                    : 0;
                if (workCount <= 0 || batchCount <= 0)
                    return;

                m_GroupedSharedDataWorks.ResizeUninitialized(workCount);
                m_SharedDataWorkGroups.ResizeUninitialized(batchCount);
                m_SharedDataWorkBatchCursors.ResizeUninitialized(batchCount);
                m_SharedDataWorkGroupBuildResult[0] = 0;
                m_PendingSharedDataWorks = m_GroupedSharedDataWorks.AsArray();
                m_PendingSharedDataPages = VividEcsPageJobExtensions.CreateEmbeddedPageSlice(
                    m_PendingSharedDataWorks,
                    pageInfoByteOffset: 0);
                m_PendingSharedDataWorkGroups = m_SharedDataWorkGroups.AsArray();
            }

            private JobHandle ScheduleSharedDataWorkGroupBuild()
            {
                if (!m_PendingSharedDataWorks.IsCreated
                    || !m_PendingSharedDataWorkGroups.IsCreated
                    || m_PendingSharedDataWorks.Length == 0
                    || m_PendingSharedDataWorkGroups.Length == 0)
                {
                    m_HasPendingSharedDataWorkGroupBuild = false;
                    return default;
                }

                m_HasPendingSharedDataWorkGroupBuild = true;
                return new ParticleSharedDataWorkGroupBuildJob
                {
                    SourceWorks = m_SharedDataWorks.AsArray(),
                    GroupedWorks = m_PendingSharedDataWorks,
                    Groups = m_PendingSharedDataWorkGroups,
                    BatchCursors = m_SharedDataWorkBatchCursors.AsArray(),
                    Result = m_SharedDataWorkGroupBuildResult,
                }.Schedule();
            }

            private bool HasUploadPageWorks()
            {
                for (int descriptorIndex = 0;
                    descriptorIndex < VividParticleRenderJobPipeline.pageJobDescriptorCount;
                    descriptorIndex++)
                {
                    ParticleRenderPageJobDescriptor descriptor =
                        VividParticleRenderJobPipeline.GetPageJobDescriptor(descriptorIndex);
                    NativeList<ParticleRenderUploadPageWork> works = GetUploadPageWorks(descriptor.Module);
                    if (works.IsCreated && works.Length > 0)
                        return true;
                }

                return false;
            }

            private void CaptureCachedUploadPageWorkCounts()
            {
                m_LastUploadPageRangeWorkCount = m_UploadPageRangeWorks.Length;
                m_LastTransformUploadPageWorkCount = m_TransformUploadPageWorks.Length;
                m_LastColorUploadPageWorkCount = m_ColorUploadPageWorks.Length;
                m_LastVelocityStretchUploadPageWorkCount = m_VelocityStretchUploadPageWorks.Length;
                m_LastUVUploadPageWorkCount = m_UVUploadPageWorks.Length;
                m_LastCustomDataUploadPageWorkCount = m_CustomDataUploadPageWorks.Length;
                m_LastMeshIndexUploadPageWorkCount = m_MeshIndexUploadPageWorks.Length;
            }

            private void ResetCachedUploadPageWorkCounts()
            {
                m_LastUploadPageRangeWorkCount = 0;
                m_LastTransformUploadPageWorkCount = 0;
                m_LastColorUploadPageWorkCount = 0;
                m_LastVelocityStretchUploadPageWorkCount = 0;
                m_LastUVUploadPageWorkCount = 0;
                m_LastCustomDataUploadPageWorkCount = 0;
                m_LastMeshIndexUploadPageWorkCount = 0;
            }

            private JobHandle ScheduleUploadPageWorkBuild()
            {
                if (!m_UploadPageRangeWorks.IsCreated || m_UploadPageRangeWorks.Length <= 0)
                    return default;

                return new ParticleBuildRenderUploadPageWorksJob
                {
                    RangeWorks = m_UploadPageRangeWorks.AsArray(),
                    TransformWorks = m_TransformUploadPageWorks.AsArray(),
                    ColorWorks = m_ColorUploadPageWorks.AsArray(),
                    VelocityStretchWorks = m_VelocityStretchUploadPageWorks.AsArray(),
                    UVWorks = m_UVUploadPageWorks.AsArray(),
                    CustomDataWorks = m_CustomDataUploadPageWorks.AsArray(),
                    MeshIndexWorks = m_MeshIndexUploadPageWorks.AsArray(),
                }.Schedule(m_UploadPageRangeWorks.Length, innerloopBatchCount: 1);
            }

            private void CapturePendingUploadPageWorks()
            {
                for (int descriptorIndex = 0;
                    descriptorIndex < VividParticleRenderJobPipeline.pageJobDescriptorCount;
                    descriptorIndex++)
                {
                    ParticleRenderPageJobDescriptor descriptor =
                        VividParticleRenderJobPipeline.GetPageJobDescriptor(descriptorIndex);
                    NativeList<ParticleRenderUploadPageWork> works = GetUploadPageWorks(descriptor.Module);
                    if (!works.IsCreated || works.Length <= 0)
                        continue;

                    SetPendingUploadPageWorks(descriptor.Module, works.AsArray());
                }
            }

            private void SetPendingUploadPageWorks(
                ParticleRenderPageJobModule module,
                NativeArray<ParticleRenderUploadPageWork> works)
            {
                switch (module)
                {
                    case ParticleRenderPageJobModule.Transform:
                        m_PendingTransformUploadPageWorks = works;
                        break;
                    case ParticleRenderPageJobModule.Color:
                        m_PendingColorUploadPageWorks = works;
                        break;
                    case ParticleRenderPageJobModule.VelocityStretch:
                        m_PendingVelocityStretchUploadPageWorks = works;
                        break;
                    case ParticleRenderPageJobModule.UV:
                        m_PendingUVUploadPageWorks = works;
                        break;
                    case ParticleRenderPageJobModule.CustomData:
                        m_PendingCustomDataUploadPageWorks = works;
                        break;
                    case ParticleRenderPageJobModule.MeshIndex:
                        m_PendingMeshIndexUploadPageWorks = works;
                        break;
                }
            }

            private bool TryAddUploadRecordWork(ParticleRenderRecord record, bool forceFullUpload)
            {
                if (record == null || record.State == null || record.Batch == null)
                    return false;

                ResetNativeUploadStats(record.RecordSlot, record.RecordVersion);
                int uploadRevision = TryGetNativePendingUploadState(
                    record.RecordSlot,
                    record.RecordVersion,
                    out ParticlePendingUploadState pendingState)
                    ? pendingState.Revision
                    : 0;
                bool hasInstanceRange = record.State.TryGetUploadRange(
                    forceFullUpload,
                    out int startIndex,
                    out int count,
                    out int columnMask,
                    out bool spanDataDirty);
                VividParticleGpuDataLayout gpuLayout = record.Batch.GpuLayout;
                uint sharedDataBits = forceFullUpload
                    ? gpuLayout.DataPerSharpBits
                    : record.State.GetPendingSharedDataBits();
                uint sharedDataFloat4Mask = forceFullUpload
                    ? SharedDataAllFloat4Mask
                    : record.State.GetPendingSharedDataFloat4Mask();
                bool hasSharedData = sharedDataBits != 0u;
                bool hasSpanData = spanDataDirty && gpuLayout.SpanSharedDataBlockBits != 0u;
                if (!ShouldQueueUploadRecordWork(hasInstanceRange, hasSharedData, hasSpanData))
                {
                    record.State.ClearUploadDirty();
                    return false;
                }

                ParticleRenderUploadSource uploadSource = default;
                bool hasUploadSource = !hasInstanceRange || record.State.TryCreateRenderUploadSource(
                    batchBaseIndex: 0,
                    batchDataOffset: 0,
                    bufferBase: null,
                    out uploadSource);
                if (hasInstanceRange && !hasUploadSource)
                {
                    record.State.ClearUploadDirty();
                    return false;
                }

                m_UploadRecordWorks.Add(new ParticleUploadRecordWork
                {
                    RecordSlot = record.RecordSlot,
                    RecordVersion = record.RecordVersion,
                    BatchIndex = record.Batch.BatchIndex,
                    StartIndex = startIndex,
                    Count = count,
                    ColumnMask = columnMask,
                    HasInstanceRange = hasInstanceRange ? 1 : 0,
                    HasUploadSource = hasInstanceRange ? 1 : 0,
                    HasSharedData = hasSharedData ? 1 : 0,
                    HasSpanData = hasSpanData ? 1 : 0,
                    SharedDataBits = sharedDataBits,
                    SharedDataFloat4Mask = sharedDataFloat4Mask,
                    UploadRevision = uploadRevision,
                    UploadSource = uploadSource,
                });
                return true;
            }

            private bool TryAddNativeUploadRecordWork(ParticleUploadRecordRef recordRef)
            {
                if (!TryGetNativeRendererRecord(
                        recordRef.RecordSlot,
                        recordRef.RecordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord)
                    || !TryGetNativePendingUploadState(
                        recordRef.RecordSlot,
                        recordRef.RecordVersion,
                        out ParticlePendingUploadState pendingState))
                {
                    return false;
                }

                pendingState.IsQueued = 0;
                ParticlePendingUploadRequest request = pendingState.Request;
                if (!request.HasData || dynamicRecord.BatchIndex < 0)
                {
                    m_NativePendingUploadStates[recordRef.RecordSlot] = pendingState;
                    return false;
                }

                dynamicRecord.LastUploadOperationCount = 0;
                dynamicRecord.LastUploadByteCount = 0;
                m_NativeRendererRecords[recordRef.RecordSlot] = dynamicRecord;
                m_NativePendingUploadStates[recordRef.RecordSlot] = pendingState;
                m_UploadRecordWorks.Add(new ParticleUploadRecordWork
                {
                    RecordSlot = recordRef.RecordSlot,
                    RecordVersion = recordRef.RecordVersion,
                    BatchIndex = dynamicRecord.BatchIndex,
                    StartIndex = request.StartIndex,
                    Count = request.Count,
                    ColumnMask = request.ColumnMask,
                    HasInstanceRange = request.HasInstanceRange,
                    HasUploadSource = request.HasUploadSource,
                    HasSharedData = request.HasSharedData,
                    HasSpanData = request.HasSpanData,
                    SharedDataBits = request.SharedDataBits,
                    SharedDataFloat4Mask = request.SharedDataFloat4Mask,
                    UploadRevision = pendingState.Revision,
                    UploadSource = request.UploadSource,
                });
                return true;
            }

            private bool DrainDirtyUploadBatchQueue()
            {
                if (!m_DirtyUploadBatchIndices.IsCreated || m_DirtyUploadBatchIndices.Length == 0)
                    return false;

                bool hasUpload = false;
                for (int dirtyIndex = 0; dirtyIndex < m_DirtyUploadBatchIndices.Length; dirtyIndex++)
                {
                    int dirtyBatchIndex = m_DirtyUploadBatchIndices[dirtyIndex];
                    if (!TryGetNativeDrawBatchRecord(
                            dirtyBatchIndex,
                            out ParticleNativeDrawBatchRecord nativeBatch))
                    {
                        m_LastInvalidDirtyUploadBatchQueueCount++;
                        continue;
                    }

                    nativeBatch.UploadDirtyQueued = 0;
                    m_NativeDrawBatchRecords[dirtyBatchIndex] = nativeBatch;
                    hasUpload |= TryAddUploadBatchWork(
                        dirtyBatchIndex,
                        nativeBatch,
                        forceFullUpload: false);
                }

                m_DirtyUploadBatchIndices.Clear();
                return hasUpload;
            }

            private bool TryAddUploadBatchWork(
                int batchIndex,
                ParticleNativeDrawBatchRecord nativeBatch,
                bool forceFullUpload)
            {
                if (nativeBatch.IsValid == 0 || batchIndex < 0)
                    return false;

                bool hasSharedValues = nativeBatch.SharedValueBufferInfoCount > 0;
                bool hasDirtySharedValues = hasSharedValues
                    && (forceFullUpload || nativeBatch.SharedValuesDirty != 0);
                if (nativeBatch.ZeroBlockDirty == 0 && !hasDirtySharedValues)
                    return false;

                ResetNativeUploadStats(
                    nativeBatch.OwnerRecordSlot,
                    nativeBatch.OwnerRecordVersion);
                m_UploadBatchWorks.Add(new ParticleUploadBatchWork
                {
                    BatchIndex = batchIndex,
                });
                return true;
            }

            private void ResetNativeUploadStats(int recordSlot, int recordVersion)
            {
                if (!TryGetNativeRendererRecord(
                        recordSlot,
                        recordVersion,
                        out ParticleRendererDynamicRecord dynamicRecord))
                {
                    return;
                }

                dynamicRecord.LastUploadOperationCount = 0;
                dynamicRecord.LastUploadByteCount = 0;
                m_NativeRendererRecords[recordSlot] = dynamicRecord;
            }

            private bool TryGetBatch(int batchIndex, out ParticleDrawBatch batch)
            {
                if ((uint)batchIndex < (uint)m_DrawBatches.Count)
                {
                    batch = m_DrawBatches[batchIndex];
                    return batch != null && batch.BatchIndex == batchIndex;
                }

                batch = null;
                return false;
            }

            private bool TryGetNativeDrawBatchRecord(
                int batchIndex,
                out ParticleNativeDrawBatchRecord nativeBatch)
            {
                if (m_NativeDrawBatchRecords.IsCreated
                    && (uint)batchIndex < (uint)m_NativeDrawBatchRecords.Length)
                {
                    nativeBatch = m_NativeDrawBatchRecords[batchIndex];
                    return nativeBatch.IsValid != 0;
                }

                nativeBatch = default;
                return false;
            }

            private void RebuildNativeDrawBatchRecords()
            {
                if (!m_NativeDrawBatchRecords.IsCreated)
                {
                    m_NativeDrawBatchRecords =
                        new NativeList<ParticleNativeDrawBatchRecord>(16, Allocator.Persistent);
                }

                if (!m_NativeRecordCopyDescriptors.IsCreated)
                {
                    m_NativeRecordCopyDescriptors =
                        new NativeList<VividParticleGpuDataCopyDescriptor>(64, Allocator.Persistent);
                }

                if (!m_NativeSharedValueBufferInfos.IsCreated)
                {
                    m_NativeSharedValueBufferInfos =
                        new NativeList<VividParticleGpuBufferDataInfo>(16, Allocator.Persistent);
                }

                if (!m_NativePerSharpValueBufferInfos.IsCreated)
                {
                    m_NativePerSharpValueBufferInfos =
                        new NativeList<VividParticleGpuBufferDataInfo>(32, Allocator.Persistent);
                }
                m_NativeDrawBatchRecords.Clear();
                m_NativeRecordCopyDescriptors.Clear();
                m_NativeSharedValueBufferInfos.Clear();
                m_NativePerSharpValueBufferInfos.Clear();
                if (m_NativeDrawBatchRecords.Capacity < m_DrawBatches.Count)
                    m_NativeDrawBatchRecords.Capacity = m_DrawBatches.Count;
                if (m_NativeRecordCopyDescriptors.Capacity < m_LastRecordCopyDescriptorCount)
                    m_NativeRecordCopyDescriptors.Capacity = m_LastRecordCopyDescriptorCount;
                if (m_NativeSharedValueBufferInfos.Capacity < m_LastSharedValueBufferInfoCount)
                    m_NativeSharedValueBufferInfos.Capacity = m_LastSharedValueBufferInfoCount;
                if (m_NativePerSharpValueBufferInfos.Capacity < m_LastPerSharpValueBufferInfoCount)
                    m_NativePerSharpValueBufferInfos.Capacity = m_LastPerSharpValueBufferInfoCount;

                m_MaxPickingDrawBuildCommandCapacity = 0;
                m_MaxBatchDrawBuildCommandCapacity = 0;
                m_MaxMeshVisibleCountOutputCapacity = 0;
                m_MaxMeshBatchVisibleCountOutputCapacity = 0;
                int rendererRecordRefCursor = 0;
                int rendererRecordRefLength = m_RendererRecordRefs.IsCreated
                    ? m_RendererRecordRefs.Length
                    : 0;

                for (int batchIndex = 0; batchIndex < m_DrawBatches.Count; batchIndex++)
                {
                    ParticleDrawBatch batch = m_DrawBatches[batchIndex];
                    int meshCommandCount = GetBatchDrawMeshCommandCount(batch);
                    int ownerRecordSlot = -1;
                    int ownerRecordVersion = 0;
                    if (batch != null
                        && batch.RecordRefCount > 0
                        && m_EcsBatchRecordRefs.IsCreated
                        && (uint)batch.RecordRefStart < (uint)m_EcsBatchRecordRefs.Length)
                    {
                        ParticleRendererRecordRef ownerRef =
                            m_EcsBatchRecordRefs[batch.RecordRefStart];
                        ownerRecordSlot = ownerRef.RecordSlot;
                        ownerRecordVersion = ownerRef.RecordVersion;
                    }

                    while (rendererRecordRefCursor < rendererRecordRefLength
                        && m_RendererRecordRefs[rendererRecordRefCursor].BatchIndex < batchIndex)
                    {
                        rendererRecordRefCursor++;
                    }

                    int rendererRecordRefStart = rendererRecordRefCursor;
                    while (rendererRecordRefCursor < rendererRecordRefLength
                        && m_RendererRecordRefs[rendererRecordRefCursor].BatchIndex == batchIndex)
                    {
                        rendererRecordRefCursor++;
                    }

                    int rendererRecordRefCount =
                        rendererRecordRefCursor - rendererRecordRefStart;
                    int copyDescriptorStart = m_NativeRecordCopyDescriptors.Length;
                    int sharedValueStart = m_NativeSharedValueBufferInfos.Length;
                    int perSharpValueStart = m_NativePerSharpValueBufferInfos.Length;
                    if (batch?.GpuBufferInfos.IsCreated == true)
                    {
                        for (int descriptorIndex = 0;
                            descriptorIndex < batch.GpuBufferInfos.Length;
                            descriptorIndex++)
                        {
                            VividParticleGpuBufferDataInfo bufferInfo =
                                batch.GpuBufferInfos[descriptorIndex];
                            if (bufferInfo.DataInfo.CreatesRecordCopyDescriptor)
                                m_NativeRecordCopyDescriptors.Add(bufferInfo.CopyDescriptor);
                            if (bufferInfo.DataInfo.Role == VividParticleGpuDataRole.SharedValue)
                                m_NativeSharedValueBufferInfos.Add(bufferInfo);
                            else if (bufferInfo.DataInfo.Role == VividParticleGpuDataRole.PerSharpValue)
                                m_NativePerSharpValueBufferInfos.Add(bufferInfo);
                        }
                    }

                    int copyDescriptorCount =
                        m_NativeRecordCopyDescriptors.Length - copyDescriptorStart;
                    int sharedValueCount = m_NativeSharedValueBufferInfos.Length - sharedValueStart;
                    int perSharpValueCount = m_NativePerSharpValueBufferInfos.Length - perSharpValueStart;

                    m_NativeDrawBatchRecords.Add(new ParticleNativeDrawBatchRecord
                    {
                        IsValid = batch != null ? 1 : 0,
                        OwnerRecordSlot = ownerRecordSlot,
                        OwnerRecordVersion = ownerRecordVersion,
                        Layer = batch?.Key.Layer ?? 0,
                        SortingPriority = batch?.SortingPriority ?? 0,
                        BatchLayer = batch?.BatchLayer ?? 0,
                        ShadowCastingMode = (int)(batch?.ShadowCastingMode ?? ShadowCastingMode.Off),
                        MotionMode = (int)(batch?.MotionMode ?? MotionVectorGenerationMode.ForceNoMotion),
                        ReceiveShadows = batch?.ReceiveShadows == true ? 1 : 0,
                        StaticShadowCaster = batch?.StaticShadowCaster == true ? 1 : 0,
                        UsesPageBillboard = batch?.UsesPageBillboard == true ? 1 : 0,
                        RequiresSortingPositions = batch?.RequiresSortingPositions == true ? 1 : 0,
                        MeshCommandCount = meshCommandCount,
                        DataOffset = batch?.DataOffset ?? 0,
                        UploadColumnLayout = batch?.UploadColumnLayout ?? CreateEmptyUploadColumnLayout(),
                        RecordCopyDescriptorStart = copyDescriptorStart,
                        RecordCopyDescriptorCount = copyDescriptorCount,
                        SharedValueBufferInfoStart = sharedValueStart,
                        SharedValueBufferInfoCount = sharedValueCount,
                        PerSharpValueBufferInfoStart = perSharpValueStart,
                        PerSharpValueBufferInfoCount = perSharpValueCount,
                        SharedDataBufferInfo = batch?.SharedDataBufferInfo ?? default,
                        SpanSharedDataBufferInfo = batch?.SpanSharedDataBufferInfo ?? default,
                        HasSharedDataBufferInfo = batch?.HasSharedDataBufferInfo == true ? 1 : 0,
                        HasSpanSharedDataBufferInfo = batch?.HasSpanSharedDataBufferInfo == true ? 1 : 0,
                        DataPerSharpBits = batch?.GpuLayout.DataPerSharpBits ?? 0u,
                        RendererRecordRefStart = rendererRecordRefStart,
                        RendererRecordRefCount = rendererRecordRefCount,
                        CullingRecordStart = -1,
                        CullingRecordCount = 0,
                        MeshVisibleCountOffset = -1,
                        MeshVisibleCountCount = 0,
                        CullingMeshIdOffset = batch?.CullingMeshIdOffset ?? -1,
                        SingleMeshVisibleCapacity = 0,
                        RenderingLayerMask = batch?.Key.RenderingLayerMask ?? 0u,
                        SceneCullingMask = batch?.SceneCullingMask ?? 0UL,
                        BatchId = batch?.BatchId ?? BatchID.Null,
                        MaterialId = batch?.MaterialId ?? default,
                        ZeroBlockDirty = 1,
                        SharedValuesDirty = 0,
                        UploadDirtyQueued = 0,
                    });
                    m_MaxBatchDrawBuildCommandCapacity += meshCommandCount;
                    m_MaxPickingDrawBuildCommandCapacity +=
                        Mathf.Max(0, batch?.RecordRefCount ?? 0) * meshCommandCount;
                    if (meshCommandCount > 1)
                    {
                        m_MaxMeshVisibleCountOutputCapacity +=
                            rendererRecordRefCount * meshCommandCount;
                        m_MaxMeshBatchVisibleCountOutputCapacity += meshCommandCount;
                    }
                }

                if (m_DirtyUploadBatchIndices.IsCreated)
                    m_DirtyUploadBatchIndices.Clear();
            }

